// Model-based exploration: seeded random command sequences, each step checked against a reference
// model interpreted from the compiled specification.
//
// Generated by `ess verify conform synthesize --target go`. Do not edit: change the specification
// and regenerate.
//
// # What this asks that the suite does not
//
// The suite asks one fixed question per scenario. This walks paths nobody wrote — a view that drops
// rows after the fifth, a refusal that still writes, an identity reused on the fourth create, a
// state that cannot be re-entered a third time — and checks after every step the outcome, the
// error, the direct events and their determined payload fields, every parameterless view over an
// entity (polling an `eventual` one), identity uniqueness and every invariant. A failure is shrunk
// to a shorter trace that still fails the same way.
//
// # External branches
//
// An outcome declared `external:` (with or without an eligibility `when:`) is a choice the
// explorer may take: where it is eligible, a seeded draw picks between it and the ordinary branch,
// the target is asked to arrange it through ConfigureExternalOutcome, and the step then expects it.
// Once a command has had a branch arranged in a sequence, the arrangement may still hold, so the
// explorer no longer expects that command's ordinary branch where an external one is eligible.
// A branch the target cannot arrange is reported `unarrangeable`, never as a disagreement.
//
// # Restarts
//
// Every sequence runs in one process lifetime unless the caller asks for restarts. With
// RestartEvery set, the explorer restarts the target after every that many commands of a sequence
// through RestartTarget, then reads every view again: the model does not change across a restart,
// so a row the restarted implementation lost is a disagreement, and an identity a later creation
// mints again — a counter kept only in the process — is the identity disagreement every creation
// is already checked for (beyond10x/ess#297). A restart draws nothing, so a seed names the same
// commands with restarts as without. A restart is a check only once a command has followed it: one
// after a sequence's last command is followed by one more drawn command, and only a restart a
// command followed counts in Restarts.Performed. A target that cannot restart is reported in
// Restarts.Unsupported and never passes.
//
// # A port, not a second opinion
//
// This file is `src/ts/explore.ts` in Go, function for function. The random draws, their order and
// every sorted enumeration are part of the contract, so one seed names one sequence in both
// languages and both report the same trace for it.
//
// # The model it reads
//
// `ir.json` beside `suite.json`, embedded here: the compact IR, the exact bytes the suite's
// `spec_digest` is taken over. It is read only after that digest matches, so a package whose two
// files came from different specifications is refused rather than explored against the wrong model.

package essconform

import (
	"context"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"math/big"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"testing"
)

//go:embed ir.json
var exploreIR string

//go:embed suite.json
var exploreSuite string

// ExploreOptions is what one exploration is asked to do.
type ExploreOptions struct {
	// Seeds is the number of sequences, seeded 1…Seeds. Zero means 200.
	Seeds int `json:"seeds,omitempty"`
	// Steps is the number of commands per sequence. Zero means 60.
	Steps int `json:"steps,omitempty"`
	// Seed, when not zero, runs exactly that one sequence and overrides Seeds: how a reported
	// failure is replayed.
	Seed int `json:"seed,omitempty"`
	// RestartEvery, when not zero, restarts the target through RestartTarget after every that many
	// commands of a sequence and checks every view again. Zero means no restart, which is what an
	// exploration did before restarts existed.
	RestartEvery int `json:"restartEvery,omitempty"`
}

// RestartTarget is what a durable implementation offers so that exploration can restart it.
// Optional: a target without it, or whose Restart returns ErrUnsupported, has restarts reported
// unsupported, which never passes.
//
// Restart stops every process of the implementation and starts it again over the same durable
// state, inside the scenario already begun, and returns once the restarted implementation answers
// requests. Clearing memory inside a process that keeps running is not a restart: a counter that
// lives in the process survives it, and that counter is what a restart is for.
type RestartTarget interface {
	Restart(scenario ScenarioContext) error
}

// RestartReach is how far the restarts an exploration was asked for got.
type RestartReach struct {
	// Every is the interval asked for, in commands.
	Every int `json:"every"`
	// Performed is the number of restarts that completed and a command then followed, across every
	// sequence and none of the shrinking replays.
	Performed int `json:"performed"`
	// Unsupported is why the target could not restart, when it could not.
	Unsupported string `json:"unsupported,omitempty"`
}

// Exclusion is one command or view left out of every sequence, and why.
type Exclusion struct {
	Subject string `json:"subject"`
	Reason  string `json:"reason"`
}

// ExploreFailure is a disagreement: its seed, what disagreed, and the shortest trace found that
// still shows it.
type ExploreFailure struct {
	Seed           int      `json:"seed"`
	Message        string   `json:"message"`
	Trace          []string `json:"trace"`
	OriginalLength int      `json:"originalLength"`
	ShrinkComplete bool     `json:"shrinkComplete"`
}

// ExploreResult is what an exploration found. Every list is sorted.
type ExploreResult struct {
	Sequences int `json:"sequences"`
	Steps     int `json:"steps"`
	// Executed is the number of commands actually run, across every sequence and none of the
	// shrinking replays.
	Executed int `json:"executed"`
	// Reached is `command/outcome` for every outcome a step took.
	Reached []string `json:"reached"`
	// Unreached is every declared outcome of an included command that no step took.
	Unreached []string    `json:"unreached"`
	Excluded  []Exclusion `json:"excluded"`
	// ExcludedOutcomes is every declared outcome of an excluded command.
	ExcludedOutcomes []string `json:"excludedOutcomes"`
	// Undetermined is what the model could not place, such as a view filter over a field no
	// command set.
	Undetermined []string `json:"undetermined"`
	// Ambiguous is every draw the specification does not decide, which was redrawn rather than
	// executed.
	Ambiguous []string `json:"ambiguous"`
	// External is every declared `external:` branch and how far the exploration got with it, in
	// order of Outcome. Absent when the specification declares none, so a result without external
	// branches keeps its bytes.
	External []ExternalReach `json:"external,omitempty"`
	// Restarts is how far the restarts RestartEvery asked for got. Absent when none were asked for,
	// so a result without restarts keeps its bytes.
	Restarts *RestartReach   `json:"restarts,omitempty"`
	Failure  *ExploreFailure `json:"failure,omitempty"`
}

// ExternalReach is one declared `external:` branch and whether a step took it.
type ExternalReach struct {
	// Outcome is `command/outcome`.
	Outcome string `json:"outcome"`
	// Cause is what the specification says decides it.
	Cause string `json:"cause"`
	// Reach is `reached`, `unreached`, `unarrangeable` (the target refused to arrange it, so no
	// step could take it) or `excluded` (its command was left out).
	Reach string `json:"reach"`
	// Reason is why the target could not arrange it, for `unarrangeable` only.
	Reason string `json:"reason,omitempty"`
}

// AssertOptions is what AssertExplored accepts.
type AssertOptions struct {
	// AllowExcluded accepts outcomes of excluded commands, and external outcomes the target could
	// not arrange. An explicit, reviewable opt-out.
	AllowExcluded bool
}

const (
	exploreDefaultSeeds = 200
	exploreDefaultSteps = 60
	exploreAttempts     = 20
	exploreShrinks      = 1000
	exploreSafeInteger  = 1<<53 - 1
)

var (
	exploreIntegers = []float64{-1, 0, 1, 2, 3, 100}
	exploreTexts    = []string{"", "a", "b"}
	exploreDigits   = regexp.MustCompile(`^-?[0-9]+$`)
)

// ErrModelMismatch is the refusal when `ir.json` is not the model `suite.json` was synthesized
// from.
var ErrModelMismatch = errors.New("`ir.json` and `suite.json` come from different specifications; regenerate the package")

// ---- randomness -------------------------------------------------------------------------------

// Mulberry32 is mulberry32 over a 32-bit state that starts at the seed.
//
// Next is the 32-bit output divided by 2^32, which a float64 holds exactly, so the TypeScript port
// draws the same numbers.
type Mulberry32 struct {
	state uint32
}

// NewMulberry32 starts a generator at seed.
func NewMulberry32(seed uint32) *Mulberry32 {
	return &Mulberry32{state: seed}
}

// NextUint32 is the next 32-bit output.
func (r *Mulberry32) NextUint32() uint32 {
	r.state += 0x6d2b79f5
	t := r.state
	t = (t ^ (t >> 15)) * (t | 1)
	t ^= t + (t^(t>>7))*(t|61)
	return t ^ (t >> 14)
}

// Next is the next output in [0, 1).
func (r *Mulberry32) Next() float64 {
	return float64(r.NextUint32()) / 4294967296
}

// Int is an integer in [lo, hi].
func (r *Mulberry32) Int(lo, hi int) int {
	return lo + int(math.Floor(r.Next()*float64(hi-lo+1)))
}

// Chance is true with probability p.
func (r *Mulberry32) Chance(p float64) bool {
	return r.Next() < p
}

func explorePick[T any](r *Mulberry32, items []T) T {
	return items[int(math.Floor(r.Next()*float64(len(items))))]
}

// ---- the model document -------------------------------------------------------------------------

// exploreLoad is the compiled model, after its digest has been checked against the suite's.
func exploreLoad(irText, suiteText string) (map[string]any, error) {
	body := strings.TrimSuffix(irText, "\n")
	sum := sha256.Sum256([]byte(body))
	suite, err := strictJSON(suiteText)
	if err != nil {
		return nil, fmt.Errorf("explore: cannot read `suite.json`: %w", err)
	}
	provenance, _ := exploreObject(suite)["provenance"].(map[string]any)
	declared, _ := provenance["spec_digest"].(string)
	if hex.EncodeToString(sum[:]) != declared {
		return nil, ErrModelMismatch
	}
	model, err := strictJSON(body)
	if err != nil {
		return nil, fmt.Errorf("explore: cannot read `ir.json`: %w", err)
	}
	ir := exploreObject(model)
	for _, command := range exploreSorted(ir["commands"]) {
		for _, raw := range exploreList(command["outcomes"]) {
			if len(exploreList(exploreObject(raw)["one_time_response"])) != 0 {
				return nil, errors.New("UnsupportedOneTimeDisclosure: one-time response concurrent/history observation is not supported")
			}
		}
	}
	return ir, nil
}

func exploreObject(value any) map[string]any {
	object, _ := value.(map[string]any)
	return object
}

func exploreList(value any) []any {
	items, _ := value.([]any)
	return items
}

func exploreString(value any) string {
	text, _ := value.(string)
	return text
}

// exploreSorted is an object's values in byte order of key.
func exploreSorted(value any) []map[string]any {
	object := exploreObject(value)
	keys := make([]string, 0, len(object))
	for key := range object {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	out := make([]map[string]any, 0, len(keys))
	for _, key := range keys {
		out = append(out, exploreObject(object[key]))
	}
	return out
}

func exploreNonEmpty(value any) bool {
	switch value := value.(type) {
	case nil:
		return false
	case []any:
		return len(value) > 0
	case map[string]any:
		return len(value) > 0
	default:
		return true
	}
}

func exploreStrings(value any) []string {
	out := []string{}
	for _, item := range exploreList(value) {
		out = append(out, fmt.Sprint(item))
	}
	return out
}

func exploreSet(items map[string]bool) []string {
	out := make([]string, 0, len(items))
	for item := range items {
		out = append(out, item)
	}
	sort.Strings(out)
	return out
}

// ---- input types --------------------------------------------------------------------------------

type exploreKind struct {
	kind     string
	variants []string
	fields   []exploreField
	entity   string
	base     *exploreKind
	why      string
}

type exploreField struct {
	name     string
	kind     exploreKind
	presence string
}

func exploreIdentityOwner(ir map[string]any, name string) string {
	for _, entity := range exploreSorted(ir["entities"]) {
		ref := exploreObject(exploreObject(entity["identity"])["type_ref"])
		if ref["kind"] == "declared" && ref["name"] == name {
			return exploreString(entity["name"])
		}
	}
	return ""
}

func exploreResolve(ir map[string]any, ref map[string]any, depth int) exploreKind {
	return exploreResolveAs(ir, ref, depth, false)
}

// exploreResolveAs is exploreResolve, and with `concurrent` it also draws a `decimal`, a `timestamp`, and a type whose
// values are constrained: concurrent exploration does not judge an answer by this model, `ess` does,
// so a drawn value outside the constraint is a question the target answers and the checker judges.
func exploreResolveAs(ir map[string]any, ref map[string]any, depth int, concurrent bool) exploreKind {
	if depth > 32 {
		return exploreKind{kind: "unsupported", why: "nested too deeply"}
	}
	if ref["kind"] == "optional" {
		base := exploreResolveAs(ir, exploreObject(ref["of"]), depth+1, concurrent)
		if base.kind == "unsupported" {
			return base
		}
		return exploreKind{kind: "optional", base: &base}
	}
	if ref["kind"] == "primitive" {
		name := exploreString(ref["name"])
		switch name {
		case "integer", "boolean", "string", "uuid":
			return exploreKind{kind: name}
		case "decimal", "timestamp":
			if concurrent {
				return exploreKind{kind: name}
			}
			return exploreKind{kind: "unsupported", why: fmt.Sprintf("a `%s`", name)}
		default:
			return exploreKind{kind: "unsupported", why: fmt.Sprintf("a `%s`", name)}
		}
	}
	if ref["kind"] != "declared" {
		return exploreKind{kind: "unsupported", why: fmt.Sprintf("a `%v`", exploreUndefined(ref["kind"]))}
	}
	name := exploreString(ref["name"])
	body := exploreObject(exploreObject(exploreObject(ir["types"])[name])["body"])
	if !concurrent && (len(exploreList(body["invariants"])) > 0 || body["alphabet"] != nil) {
		return exploreKind{kind: "unsupported", why: fmt.Sprintf("`%s`, which constrains its values", name)}
	}
	switch body["kind"] {
	case "newtype":
		base := exploreResolveAs(ir, exploreObject(body["of"]), depth+1, concurrent)
		if base.kind == "unsupported" {
			return base
		}
		if owner := exploreIdentityOwner(ir, name); owner != "" {
			return exploreKind{kind: "identity", entity: owner, base: &base}
		}
		return base
	case "enum":
		variants := []string{}
		for _, variant := range exploreList(body["variants"]) {
			if text, ok := variant.(string); ok {
				variants = append(variants, text)
			} else {
				variants = append(variants, fmt.Sprint(exploreObject(variant)["name"]))
			}
		}
		if len(variants) == 0 {
			return exploreKind{kind: "unsupported", why: fmt.Sprintf("`%s`, which has no variants", name)}
		}
		return exploreKind{kind: "enum", variants: variants}
	case "struct":
		fields := []exploreField{}
		for _, field := range exploreList(body["fields"]) {
			field := exploreObject(field)
			kind := exploreResolveAs(ir, exploreObject(field["type_ref"]), depth+1, concurrent)
			if kind.kind == "unsupported" {
				return kind
			}
			fields = append(fields, exploreField{name: exploreString(field["name"]), kind: kind, presence: exploreString(exploreObject(field["naming"])["presence"])})
		}
		return exploreKind{kind: "struct", fields: fields}
	default:
		return exploreKind{kind: "unsupported", why: fmt.Sprintf("`%s`, a `%v`", name, exploreUndefined(body["kind"]))}
	}
}

// exploreUndefined spells an absent value the way a TypeScript template literal does.
func exploreUndefined(value any) any {
	if value == nil {
		return "undefined"
	}
	return value
}

// ---- predicates ---------------------------------------------------------------------------------

var exploreTextOperators = []string{"starts_with", "ends_with", "contains"}

func exploreWalk(p predicate, visit func(predicate)) {
	visit(p)
	for _, child := range p.children {
		exploreWalk(child, visit)
	}
	if p.body != nil {
		exploreWalk(*p.body, visit)
	}
}

// explorePaths is every fact path a predicate reads, sorted.
func explorePaths(p predicate) []string {
	found := map[string]bool{}
	exploreWalk(p, func(node predicate) {
		switch {
		case node.kind == "compare":
			if node.left.isFact {
				found[node.left.path] = true
			}
			if node.right.isFact {
				found[node.right.path] = true
			}
		case node.kind == "forall" || node.kind == "exists":
			found[node.over] = true
		case node.path != "":
			found[node.path] = true
		}
	})
	return exploreSet(found)
}

// exploreMissing is the first path a predicate reads that row does not hold.
func exploreMissing(p predicate, row Row) string {
	source := facts(row)
	all := explorePaths(p)
	for _, path := range all {
		if _, ok := source[path]; !ok {
			return path
		}
	}
	if len(all) > 0 {
		return all[0]
	}
	return ""
}

func exploreParse(node any) (predicate, string) {
	p, err := fromNode(node)
	if err != nil {
		return predicate{}, "it cannot be read: " + err.Error()
	}
	text := ""
	exploreWalk(p, func(child predicate) {
		for _, operator := range exploreTextOperators {
			if text == "" && child.kind == operator {
				text = operator
			}
		}
	})
	if text != "" {
		return predicate{}, fmt.Sprintf("it uses `%s`, which this explorer does not evaluate", text)
	}
	return p, ""
}

type explorePools struct {
	integers []float64
	texts    []string
	// fieldIntegers and fieldTexts are the pools of the input paths whose own pool differs from
	// the command's (beyond10x/ess#223): the command's, with the input's `example:` and, for a
	// text, that example (or the path itself) cut or cycled to n-1, n and n+1 characters for each
	// `.count` literal compared with the input. Every other path draws from the command's pool.
	fieldIntegers map[string][]float64
	fieldTexts    map[string][]string
	// fieldEnums is the variants of each enum input with an `example:`, and the example where it is
	// not one of them. Validation admits only a declared variant, so for a validated specification
	// this is the variants as declared and the draw does not move.
	fieldEnums map[string][]string
}

// exploreMaxCount is the longest text a `.count` boundary is drawn at, synthesis's
// MAX_COUNT_WITNESS.
const exploreMaxCount = 1024

// integersAt is the integer pool the input at path draws from.
func (p explorePools) integersAt(path string) []float64 {
	if pool, ok := p.fieldIntegers[path]; ok {
		return pool
	}
	return p.integers
}

// enumsAt is the pool an enum input at path draws from, variants where it has no example.
func (p explorePools) enumsAt(path string, variants []string) []string {
	if pool, ok := p.fieldEnums[path]; ok {
		return pool
	}
	return variants
}

// textsAt is the text pool the input at path draws from.
func (p explorePools) textsAt(path string) []string {
	if pool, ok := p.fieldTexts[path]; ok {
		return pool
	}
	return p.texts
}

// exploreSafeWhole is value as a whole number a binary64 holds exactly, if it is one.
func exploreSafeWhole(value Node) (float64, bool) {
	switch value.(type) {
	case string, bool, nil:
		return 0, false
	}
	number, ok := numberValue(value)
	if !ok || !number.IsInt() {
		return 0, false
	}
	whole := number.Num()
	if whole.CmpAbs(big.NewInt(exploreSafeInteger)) > 0 {
		return 0, false
	}
	return float64(whole.Int64()), true
}

// exploreCounts is, for each input path a `.count` of which a guard compares with a whole
// literal, the lengths n-1, n and n+1 of every such literal n, from 0 to exploreMaxCount. A guard
// over the input reads its paths as they are; a predicate over the stored row reads the input under
// `input.`, and its other paths are the row's.
func exploreCounts(inputGuards, storedGuards []predicate) map[string]map[int]bool {
	counts := map[string]map[int]bool{}
	visit := func(stored bool) func(predicate) {
		return func(node predicate) {
			if node.kind != "compare" {
				return
			}
			for _, pair := range [][2]operand{{node.left, node.right}, {node.right, node.left}} {
				fact, literal := pair[0], pair[1]
				if !fact.isFact || literal.isFact {
					continue
				}
				path, counted := strings.CutSuffix(fact.path, ".count")
				if !counted || path == "" {
					continue
				}
				if stored {
					if path, counted = strings.CutPrefix(path, "input."); !counted {
						continue
					}
				}
				n, ok := exploreSafeWhole(literal.literal)
				if !ok {
					continue
				}
				for _, length := range []float64{n - 1, n, n + 1} {
					if length < 0 || length > exploreMaxCount {
						continue
					}
					if counts[path] == nil {
						counts[path] = map[int]bool{}
					}
					counts[path][int(length)] = true
				}
			}
		}
	}
	for _, guard := range inputGuards {
		exploreWalk(guard, visit(false))
	}
	for _, guard := range storedGuards {
		exploreWalk(guard, visit(true))
	}
	return counts
}

// exploreResize is text at exactly length characters: its first length when it has that many,
// otherwise its own characters cycled from its start, and plain's when it is empty. Synthesis's
// rule for a text cut to a `.count` boundary (`witness.rs` `resize`).
func exploreResize(text string, length int, plain string) string {
	source := []rune(text)
	if len(source) == 0 {
		source = []rune(plain)
	}
	if len(source) == 0 {
		return ""
	}
	out := make([]rune, 0, length)
	for index := 0; index < length; index++ {
		out = append(out, source[index%len(source)])
	}
	return string(out)
}

// exploreLeafKind is the kind a value is drawn as once an `Optional` and an identity are looked
// through.
func exploreLeafKind(kind exploreKind) exploreKind {
	for (kind.kind == "optional" || kind.kind == "identity") && kind.base != nil {
		kind = *kind.base
	}
	return kind
}

// exploreFieldPools gives each input path its own pool where it differs from the command's
// (beyond10x/ess#223). examples is the command's `examples`, by top-level input name.
func exploreFieldPools(pools *explorePools, inputs []exploreField, examples map[string]any, counts map[string]map[int]bool) {
	pools.fieldIntegers = map[string][]float64{}
	pools.fieldTexts = map[string][]string{}
	pools.fieldEnums = map[string][]string{}
	var visit func(path string, kind exploreKind, example Node, hasExample bool)
	visit = func(path string, kind exploreKind, example Node, hasExample bool) {
		leaf := exploreLeafKind(kind)
		switch leaf.kind {
		case "struct":
			for _, field := range leaf.fields {
				visit(path+"."+field.name, field.kind, nil, false)
			}
		case "enum":
			text, isText := example.(string)
			if !hasExample || !isText {
				return
			}
			pool := append([]string{}, leaf.variants...)
			if !exploreContains(pool, text) {
				pool = append(pool, text)
			}
			pools.fieldEnums[path] = pool
		case "integer":
			n, ok := exploreSafeWhole(example)
			if !hasExample || !ok {
				return
			}
			set := map[float64]bool{n: true}
			for _, value := range pools.integers {
				set[value] = true
			}
			pool := make([]float64, 0, len(set))
			for value := range set {
				pool = append(pool, value)
			}
			sort.Float64s(pool)
			pools.fieldIntegers[path] = pool
		case "string":
			text, isText := example.(string)
			isText = isText && hasExample
			if !isText && len(counts[path]) == 0 {
				return
			}
			set := map[string]bool{}
			for _, value := range pools.texts {
				set[value] = true
			}
			base := path
			if isText {
				set[text] = true
				base = text
			}
			for length := range counts[path] {
				set[exploreResize(base, length, path)] = true
			}
			pools.fieldTexts[path] = exploreSet(set)
		}
	}
	for _, field := range inputs {
		example, hasExample := examples[field.name]
		visit(field.name, field.kind, example, hasExample)
	}
}

// exploreLiterals is the literals a command's guards compare against, as draw pools.
func exploreLiterals(guards []predicate) explorePools {
	integers := map[float64]bool{}
	for _, value := range exploreIntegers {
		integers[value] = true
	}
	texts := map[string]bool{}
	for _, value := range exploreTexts {
		texts[value] = true
	}
	literal := func(value Node) {
		switch value := value.(type) {
		case string:
			texts[value] = true
			return
		case bool, nil:
			return
		}
		number, ok := numberValue(value)
		if !ok || !number.IsInt() {
			return
		}
		whole := number.Num()
		if whole.CmpAbs(big.NewInt(exploreSafeInteger)) > 0 {
			return
		}
		n := float64(whole.Int64())
		integers[n-1] = true
		integers[n] = true
		integers[n+1] = true
	}
	for _, guard := range guards {
		exploreWalk(guard, func(node predicate) {
			switch node.kind {
			case "compare":
				if !node.left.isFact {
					literal(node.left.literal)
				}
				if !node.right.isFact {
					literal(node.right.literal)
				}
			case "any_of", "none_of":
				for _, value := range node.values {
					literal(value)
				}
			}
		})
	}
	pools := explorePools{}
	for value := range integers {
		pools.integers = append(pools.integers, value)
	}
	sort.Float64s(pools.integers)
	pools.texts = exploreSet(texts)
	return pools
}

// ---- the plan: what is explored, and what is left out -------------------------------------------

type exploreCommand struct {
	name   string
	actor  string
	node   map[string]any
	inputs []exploreField
	guards map[string]predicate
	// rows is every branch selected by the stored row (beyond10x/ess#221), by outcome name.
	rows  map[string]exploreRowGuard
	pools explorePools
}

// exploreRowGuard is a condition read from the subject's stored row: its held state
// (`subject_state`, `state_change`), one stored enum field (`subject_field`) or a predicate over
// its stored fields (`subject_predicate`), each with an optional guard over the input.
type exploreRowGuard struct {
	kind   string
	states map[string]bool
	field  string
	equals string
	stored *predicate
	input  *predicate
}

// exploreRowKinds is every condition read from the subject's stored row.
var exploreRowKinds = []string{"subject_state", "state_change", "subject_field", "subject_predicate"}

type exploreDeclared struct {
	command  string
	outcomes []string
}

type exploreExternal struct {
	command string
	id      string
	cause   string
}

type explorePlan struct {
	ir               map[string]any
	system           string
	commands         []*exploreCommand
	views            []map[string]any
	excluded         []Exclusion
	excludedCommands map[string]bool
	declared         []exploreDeclared
	// externals is every declared external branch, in declaration order.
	externals []exploreExternal
	// unarrangeable is `command/outcome` for every external branch the target refused to arrange,
	// and its reason.
	unarrangeable map[string]string
	// sendable is every command excluded only because exploration cannot draw one of its inputs
	// (a list, say): a precondition supplies its input as a literal, so it may still send one
	// (beyond10x/ess#205). No sequence draws it.
	sendable map[string]*exploreCommand
}

// exploreIsExternal is true for an outcome an external cause decides.
func exploreIsExternal(outcome map[string]any) bool {
	kind := exploreObject(outcome["condition"])["kind"]
	return kind == "external" || kind == "external_when"
}

func exploreEffectRefusal(outcome map[string]any) string {
	subject := exploreObject(outcome["subject"])
	if subject == nil {
		return ""
	}
	from := exploreObject(subject["instance"])["from"]
	effect := subject["effect"]
	allowed := (effect == "creates" && from == "observed") ||
		((effect == "moves" || effect == "updates") && from == "supplied")
	if allowed {
		return ""
	}
	return fmt.Sprintf("outcome `%v` %v its subject from `%v`", outcome["name"], exploreUndefined(effect), exploreUndefined(from))
}

// exploreRowOf is a stored-row condition as the explorer evaluates it, or why it cannot.
func exploreRowOf(condition map[string]any) (exploreRowGuard, string) {
	row := exploreRowGuard{kind: exploreString(condition["kind"]), states: map[string]bool{}}
	parse := func(node any) (*predicate, string) {
		if node == nil {
			return nil, ""
		}
		parsed, refusal := exploreParse(node)
		if refusal != "" {
			return nil, refusal
		}
		return &parsed, ""
	}
	var refusal string
	switch row.kind {
	case "subject_state":
		// One state is written as the state itself, a list (ess/18) as a list.
		if state, ok := condition["state"].(string); ok {
			row.states[state] = true
		}
		for _, state := range exploreStrings(condition["state"]) {
			row.states[state] = true
		}
		row.input, refusal = parse(condition["predicate"])
	case "state_change":
		for _, state := range exploreStrings(condition["states"]) {
			row.states[state] = true
		}
		row.input, refusal = parse(condition["predicate"])
	case "subject_field":
		row.field = exploreString(condition["field"])
		row.equals = exploreString(condition["equals"])
		row.input, refusal = parse(condition["predicate"])
	case "subject_predicate":
		row.stored, refusal = parse(condition["predicate"])
		if refusal == "" {
			row.input, refusal = parse(condition["input"])
		}
	}
	return row, refusal
}

// exploreExistingIn is the `existing_instance` branch of a command node, or nil.
func exploreExistingIn(node map[string]any) map[string]any {
	for _, item := range exploreList(node["outcomes"]) {
		outcome := exploreObject(item)
		if exploreObject(outcome["condition"])["kind"] == "existing_instance" {
			return outcome
		}
	}
	return nil
}

// exploreAddress is where a creating branch puts its identity: the entity, and the input field
// that names the identity, or "" where the implementation generates it.
type exploreAddress struct {
	entity string
	field  string
}

// exploreAddresses is the distinct addresses of a command node's creating branches, in
// declaration order. Where there is more than one, which one an `existing_instance` branch reads
// depends on the branch selected (`interpret::execute` `existence::existing`).
func exploreAddresses(node map[string]any) []exploreAddress {
	out := []exploreAddress{}
	for _, item := range exploreList(node["outcomes"]) {
		outcome := exploreObject(item)
		subject := exploreObject(outcome["subject"])
		if subject["effect"] != "creates" {
			continue
		}
		instance := exploreObject(subject["instance"])
		identity := exploreString(exploreObject(instance["field"])["name"])
		address := exploreAddress{entity: exploreString(subject["entity"])}
		for _, payload := range exploreList(outcome["payload"]) {
			payload := exploreObject(payload)
			if payload["event"] != instance["event"] {
				continue
			}
			for _, field := range exploreList(payload["fields"]) {
				field := exploreObject(field)
				value := exploreObject(field["value"])
				if exploreString(field["target"]) == identity && (value["kind"] == "input_field" || value["kind"] == "input_or_generated") {
					address.field = exploreString(value["field"])
				}
			}
		}
		known := false
		for _, earlier := range out {
			known = known || earlier == address
		}
		if !known {
			out = append(out, address)
		}
	}
	return out
}

func explorePlanOf(ir map[string]any) *explorePlan {
	return explorePlanAs(ir, false)
}

// explorePlanAs is explorePlanOf, and with `concurrent` it resolves inputs as exploreResolveAs does and
// keeps a command no actor may invoke, which is then sent with no actor.
func explorePlanAs(ir map[string]any, concurrent bool) *explorePlan {
	p := &explorePlan{ir: ir, system: fmt.Sprint(ir["system"]), excluded: []Exclusion{}, excludedCommands: map[string]bool{}, unarrangeable: map[string]string{}, sendable: map[string]*exploreCommand{}}
	actorFor := map[string]string{}
	for _, actor := range exploreSorted(ir["actors"]) {
		for _, command := range exploreStrings(actor["may"]) {
			if _, ok := actorFor[command]; !ok {
				actorFor[command] = exploreString(actor["name"])
			}
		}
	}

	for _, node := range exploreSorted(ir["commands"]) {
		name := exploreString(node["name"])
		outcomes := exploreList(node["outcomes"])
		names := []string{}
		for _, outcome := range outcomes {
			names = append(names, fmt.Sprint(exploreObject(outcome)["name"]))
			if exploreIsExternal(exploreObject(outcome)) {
				p.externals = append(p.externals, exploreExternal{
					command: name,
					id:      name + "/" + fmt.Sprint(exploreObject(outcome)["name"]),
					cause:   exploreString(exploreObject(exploreObject(outcome)["condition"])["cause"]),
				})
			}
		}
		p.declared = append(p.declared, exploreDeclared{command: name, outcomes: names})
		reason := ""
		for _, outcome := range outcomes {
			kind := exploreObject(exploreObject(outcome)["condition"])["kind"]
			// A condition read from the stored row, and existence of the identity a creation names,
			// are decided from the model's rows (beyond10x/ess#221). Concurrent exploration does not
			// draw them: it keeps the commands it always drew.
			stored := !concurrent && (kind == "existing_instance" || exploreContains(exploreRowKinds, fmt.Sprint(kind)))
			if reason == "" && kind != "when" && kind != "otherwise" && kind != "wrong_state" &&
				kind != "external" && kind != "external_when" && kind != "unknown_instance" && !stored {
				reason = fmt.Sprintf("outcome `%v` has a `%v` condition", exploreObject(outcome)["name"], exploreUndefined(kind))
			}
		}
		if existing := exploreExistingIn(node); reason == "" && existing != nil && len(exploreAddresses(node)) > 1 {
			reason = fmt.Sprintf("outcome `%v` answers an existing instance of creations that name it differently", existing["name"])
		}
		for _, outcome := range outcomes {
			if reason == "" {
				reason = exploreEffectRefusal(exploreObject(outcome))
			}
		}
		for _, outcome := range outcomes {
			if reason == "" && !concurrent && exploreObject(outcome)["replays"] != nil {
				reason = fmt.Sprintf("outcome `%v` replays a retained result", exploreObject(outcome)["name"])
			}
		}
		// undrawable is why exploration cannot draw an input, kept apart from every other reason so
		// that a command excluded for it alone stays sendable by a precondition. It is reported in
		// the order it always was: after the outcome reasons, before the guard and actor ones.
		undrawable := ""
		inputs := []exploreField{}
		for _, field := range exploreList(node["input"]) {
			field := exploreObject(field)
			kind := exploreResolveAs(ir, exploreObject(field["type_ref"]), 0, concurrent)
			if undrawable == "" && kind.kind == "unsupported" {
				undrawable = fmt.Sprintf("input `%v` is %s", field["name"], kind.why)
			}
			inputs = append(inputs, exploreField{name: exploreString(field["name"]), kind: kind, presence: exploreString(exploreObject(field["naming"])["presence"])})
		}
		guards := map[string]predicate{}
		rows := map[string]exploreRowGuard{}
		ordered := []predicate{}
		// inputGuards read the input as it is; storedGuards read the row, and the input under `input.`.
		inputGuards := []predicate{}
		storedGuards := []predicate{}
		later := ""
		for _, outcome := range outcomes {
			outcome := exploreObject(outcome)
			condition := exploreObject(outcome["condition"])
			if reason != "" || later != "" {
				continue
			}
			if exploreContains(exploreRowKinds, fmt.Sprint(condition["kind"])) {
				row, refusal := exploreRowOf(condition)
				if refusal != "" {
					later = fmt.Sprintf("the guard of `%v`: %s", outcome["name"], refusal)
					continue
				}
				rows[fmt.Sprint(outcome["name"])] = row
				if row.stored != nil {
					ordered = append(ordered, *row.stored)
					storedGuards = append(storedGuards, *row.stored)
				}
				if row.input != nil {
					ordered = append(ordered, *row.input)
					inputGuards = append(inputGuards, *row.input)
				}
				continue
			}
			if condition["kind"] != "when" && condition["kind"] != "external_when" {
				continue
			}
			guard, refusal := exploreParse(condition["predicate"])
			if refusal != "" {
				later = fmt.Sprintf("the guard of `%v`: %s", outcome["name"], refusal)
				continue
			}
			guards[fmt.Sprint(outcome["name"])] = guard
			ordered = append(ordered, guard)
			inputGuards = append(inputGuards, guard)
		}
		actor, ok := actorFor[name]
		if later == "" && !ok && !concurrent {
			later = "no actor may invoke it"
		}
		pools := exploreLiterals(ordered)
		exploreFieldPools(&pools, inputs, exploreObject(node["examples"]), exploreCounts(inputGuards, storedGuards))
		command := &exploreCommand{
			name: name, actor: actor, node: node, inputs: inputs, guards: guards, rows: rows, pools: pools,
		}
		if reason == "" && later == "" && undrawable != "" {
			p.sendable[name] = command
		}
		for _, next := range []string{undrawable, later} {
			if reason == "" {
				reason = next
			}
		}
		if reason != "" {
			p.excluded = append(p.excluded, Exclusion{Subject: name, Reason: reason})
			p.excludedCommands[name] = true
			continue
		}
		p.commands = append(p.commands, command)
	}

	for _, view := range exploreSorted(ir["views"]) {
		reason := ""
		aggregates := false
		for _, field := range exploreList(view["fields"]) {
			if exploreNonEmpty(exploreObject(field)["aggregate"]) {
				aggregates = true
			}
		}
		switch {
		case exploreNonEmpty(view["params"]):
			reason = "it declares parameters"
		case exploreNonEmpty(view["group_by"]):
			reason = "it groups its rows"
		case aggregates:
			reason = "it aggregates"
		case exploreObject(exploreObject(ir["entities"])[exploreString(view["source"])]) == nil:
			reason = fmt.Sprintf("its source `%v` is not an entity", exploreUndefined(view["source"]))
		case view["filter"] != nil:
			if _, refusal := exploreParse(view["filter"]); refusal != "" {
				reason = "its filter: " + refusal
			}
		}
		if reason != "" {
			p.excluded = append(p.excluded, Exclusion{Subject: exploreString(view["name"]), Reason: reason})
		} else {
			p.views = append(p.views, view)
		}
	}
	return p
}

func (p *explorePlan) exclude(subject, reason string) {
	p.excluded = append(p.excluded, Exclusion{Subject: subject, Reason: reason})
	kept := []*exploreCommand{}
	for _, command := range p.commands {
		if command.name == subject {
			p.excludedCommands[subject] = true
		} else {
			kept = append(kept, command)
		}
	}
	p.commands = kept
	views := []map[string]any{}
	for _, view := range p.views {
		if view["name"] != subject {
			views = append(views, view)
		}
	}
	p.views = views
}

func (p *explorePlan) command(name string) *exploreCommand {
	for _, command := range p.commands {
		if command.name == name {
			return command
		}
	}
	return nil
}

// ---- the reference model ------------------------------------------------------------------------

type exploreRecord struct {
	id     Node
	fields Row
}

type exploreModel struct {
	records map[string][]*exploreRecord
}

func (m *exploreModel) of(entity string) []*exploreRecord {
	return m.records[entity]
}

func (m *exploreModel) find(entity string, id Node) *exploreRecord {
	for _, record := range m.records[entity] {
		if equal(record.id, id) {
			return record
		}
	}
	return nil
}

// A value an outcome gives a field: determined, undetermined, or cleared.
const (
	exploreDetermined = iota
	exploreUndetermined
	exploreCleared
)

func exploreReadPath(value Node, path string) (Node, bool) {
	current := value
	for _, segment := range strings.Split(path, ".") {
		object, ok := current.(map[string]any)
		if !ok {
			return nil, false
		}
		next, ok := object[segment]
		if !ok {
			return nil, false
		}
		current = next
	}
	return current, true
}

func exploreSetPath(value map[string]any, path string, to Node) {
	segments := strings.Split(path, ".")
	current := value
	for _, segment := range segments[:len(segments)-1] {
		current = current[segment].(map[string]any)
	}
	current[segments[len(segments)-1]] = to
}

func exploreCopy(value Node) Node {
	switch value := value.(type) {
	case map[string]any:
		out := map[string]any{}
		for key, nested := range value {
			out[key] = exploreCopy(nested)
		}
		return out
	case []any:
		out := make([]any, len(value))
		for index, nested := range value {
			out[index] = exploreCopy(nested)
		}
		return out
	default:
		return value
	}
}

func exploreLiteral(ir map[string]any, text any, ref map[string]any) (Node, bool) {
	kind := exploreResolve(ir, ref, 0)
	if kind.kind == "identity" {
		kind = *kind.base
	}
	written, ok := text.(string)
	if !ok {
		return nil, false
	}
	switch kind.kind {
	case "integer":
		if !exploreDigits.MatchString(written) {
			return nil, false
		}
		number, err := strconv.ParseInt(written, 10, 64)
		if err != nil || number > exploreSafeInteger || number < -exploreSafeInteger {
			return nil, false
		}
		return float64(number), true
	case "boolean":
		switch written {
		case "true":
			return true, true
		case "false":
			return false, true
		}
		return nil, false
	case "string", "uuid", "enum":
		return written, true
	default:
		return nil, false
	}
}

func exploreOptionalType(ir, ref map[string]any) bool {
	for depth := 0; depth <= 32; depth++ {
		if ref["kind"] == "optional" {
			return true
		}
		if ref["kind"] != "declared" {
			return false
		}
		body := exploreObject(exploreObject(exploreObject(ir["types"])[exploreString(ref["name"])])["body"])
		if body["kind"] != "newtype" {
			return false
		}
		ref = exploreObject(body["of"])
	}
	return false
}

func exploreValue(ir map[string]any, value map[string]any, input Row, ref map[string]any) (Node, int) {
	switch value["kind"] {
	case "input_field":
		found, ok := exploreReadPath(map[string]any(input), fmt.Sprint(value["field"]))
		if !ok {
			if exploreOptionalType(ir, exploreObject(value["type_ref"])) {
				return nil, exploreDetermined
			}
			return nil, exploreUndetermined
		}
		return found, exploreDetermined
	case "literal":
		found, ok := exploreLiteral(ir, value["value"], ref)
		if !ok {
			return nil, exploreUndetermined
		}
		return found, exploreDetermined
	case "cleared":
		return nil, exploreCleared
	default:
		return nil, exploreUndetermined
	}
}

// Typed absence is knowledge; only genuinely unknown model fields are skipped.
func exploreValueAgrees(ir map[string]any, ref, naming map[string]any, expected, actual Node, present bool, depth int) bool {
	if depth > 32 {
		return false
	}
	if ref["kind"] == "optional" {
		if expected == nil {
			switch naming["presence"] {
			case "null_when_absent":
				return present && actual == nil
			case "omitted_when_absent":
				return !present
			default:
				return !present || actual == nil
			}
		}
		return exploreValueAgrees(ir, exploreObject(ref["of"]), nil, expected, actual, present, depth+1)
	}
	if ref["kind"] == "declared" {
		body := exploreObject(exploreObject(exploreObject(ir["types"])[exploreString(ref["name"])])["body"])
		if body["kind"] == "newtype" {
			return exploreValueAgrees(ir, exploreObject(body["of"]), naming, expected, actual, present, depth+1)
		}
		if body["kind"] == "struct" && exploreObject(expected) != nil {
			if !present || exploreObject(actual) == nil {
				return false
			}
			names := map[string]bool{}
			for _, item := range exploreList(body["fields"]) {
				names[exploreString(exploreObject(item)["name"])] = true
			}
			for name := range exploreObject(actual) {
				if !names[name] {
					return false
				}
			}
			for _, item := range exploreList(body["fields"]) {
				field := exploreObject(item)
				name := exploreString(field["name"])
				got, has := exploreObject(actual)[name]
				if !exploreValueAgrees(ir, exploreObject(field["type_ref"]), exploreObject(field["naming"]), exploreObject(expected)[name], got, has, depth+1) {
					return false
				}
			}
			return true
		}
	}
	return present && equal(expected, actual)
}

// exploreDecision is what the model says one step may take. For `take`, outcome is the ordinary
// branch (nil when none holds) and externals the external branches eligible for this input and
// this subject, in declaration order; at least one of the two is present. A `take` with no
// ordinary branch carries in names the ambiguity it stands in for, reported if no external branch
// can be arranged. `unknown` and `undetermined` carry in reason a guard the model cannot
// evaluate: over the input, which excludes the command, or over a stored field no command set,
// which is redrawn and reported.
type exploreDecision struct {
	kind      string
	outcome   map[string]any
	externals []map[string]any
	names     []string
	reason    string
}

func exploreSupplied(command *exploreCommand) map[string]any {
	for _, outcome := range exploreList(command.node["outcomes"]) {
		outcome := exploreObject(outcome)
		if exploreObject(exploreObject(outcome["subject"])["instance"])["from"] == "supplied" {
			return outcome
		}
	}
	return nil
}

func exploreUnknown(command *exploreCommand) map[string]any {
	for _, item := range exploreList(command.node["outcomes"]) {
		outcome := exploreObject(item)
		if exploreObject(outcome["condition"])["kind"] == "unknown_instance" {
			return outcome
		}
	}
	return nil
}

func exploreTerminal(command *exploreCommand, outcome map[string]any, input Row, model *exploreModel) map[string]any {
	subject := exploreObject(outcome["subject"])
	instance := exploreObject(subject["instance"])
	if instance["from"] == "supplied" {
		id, _ := exploreReadPath(map[string]any(input), exploreString(exploreObject(instance["field"])["name"]))
		if model.find(exploreString(subject["entity"]), id) == nil {
			if missing := exploreUnknown(command); missing != nil {
				return missing
			}
		}
	}
	return outcome
}

func exploreFrom(outcome map[string]any) []string {
	return exploreStrings(exploreObject(exploreObject(outcome["subject"])["transition"])["from"])
}

func exploreContains(items []string, item string) bool {
	for _, candidate := range items {
		if candidate == item {
			return true
		}
	}
	return false
}

// exploreIsInputRefusal is whether outcome is an input-guarded refusal: a `when:` and an `error:`,
// which Entity Runtime tries before every other branch.
func exploreIsInputRefusal(outcome map[string]any) bool {
	return exploreObject(outcome["condition"])["kind"] == "when" && exploreString(outcome["error"]) != ""
}

// exploreAllMove is whether every one of outcomes moves its subject.
func exploreAllMove(outcomes []map[string]any) bool {
	for _, outcome := range outcomes {
		if exploreObject(outcome["subject"])["effect"] != "moves" {
			return false
		}
	}
	return true
}

// exploreDecide is which branch a step takes, in Entity Runtime's order (beyond10x/ess#235): the
// input-guarded refusals, the first declared whose guard holds; then the accepting guarded branch
// that holds, or the default; then, where that branch moves from a state no move of the command
// starts from, the wrong-state branch.
func exploreDecide(command *exploreCommand, input Row, model *exploreModel) exploreDecision {
	outcomes := []map[string]any{}
	for _, outcome := range exploreList(command.node["outcomes"]) {
		outcomes = append(outcomes, exploreObject(outcome))
	}
	supplied := exploreSupplied(command)
	var record *exploreRecord
	if supplied != nil {
		subject := exploreObject(supplied["subject"])
		field := exploreString(exploreObject(exploreObject(subject["instance"])["field"])["name"])
		id, _ := exploreReadPath(map[string]any(input), field)
		record = model.find(exploreString(subject["entity"]), id)
	}
	moves := 0
	starts := map[string]bool{}
	var wrong map[string]any
	for _, outcome := range outcomes {
		if exploreObject(outcome["subject"])["effect"] == "moves" {
			moves++
			for _, state := range exploreFrom(outcome) {
				starts[state] = true
			}
		}
		if wrong == nil && exploreObject(outcome["condition"])["kind"] == "wrong_state" {
			wrong = outcome
		}
	}
	source := facts(input)
	// Entity Runtime's order (beyond10x/ess#235): an input-guarded refusal, the first declared
	// whose guard holds, answers before anything else is read — the record, its state, a provider,
	// and every accepting branch it overlaps.
	for _, outcome := range outcomes {
		if !exploreIsInputRefusal(outcome) {
			continue
		}
		guard := command.guards[fmt.Sprint(outcome["name"])]
		switch guard.evaluate(source) {
		case truthUnknown:
			return exploreDecision{kind: "unknown", reason: fmt.Sprintf("the guard of `%v` (%s) is unknown over a generated input", outcome["name"], guard)}
		case truthTrue:
			return exploreDecision{kind: "take", outcome: outcome}
		}
	}
	// Existence (beyond10x/ess#221): a creation naming an identity a record already carries is
	// refused by `existing_instance`, before the held state and every accepting branch.
	if existing := exploreExistingIn(command.node); existing != nil {
		for _, address := range exploreAddresses(command.node) {
			if address.field == "" {
				continue
			}
			if id, ok := exploreReadPath(map[string]any(input), address.field); ok && id != nil && model.find(address.entity, id) != nil {
				return exploreDecision{kind: "take", outcome: existing}
			}
		}
	}
	if supplied != nil && record == nil && exploreUnknown(command) == nil {
		return exploreDecision{kind: "ambiguous", names: []string{"no record for the supplied instance"}}
	}
	// A branch selected by the stored row reads a row that must exist: an identity no record
	// carries is the unknown-instance answer before any of them is read.
	if len(command.rows) > 0 && record == nil {
		if missing := exploreUnknown(command); missing != nil {
			return exploreDecision{kind: "take", outcome: missing}
		}
		return exploreDecision{kind: "ambiguous", names: []string{"no record for the supplied instance"}}
	}
	// orExternal is what a step may take where no ordinary branch can be: the eligible external
	// branches alone, or otherwise, when there are none.
	orExternal := func(otherwise exploreDecision) exploreDecision {
		externals, unknown := exploreEligible(command, outcomes, source, record)
		if unknown != "" {
			return exploreDecision{kind: "unknown", reason: unknown}
		}
		if len(externals) > 0 {
			return exploreDecision{kind: "take", externals: externals, names: otherwise.names}
		}
		return otherwise
	}
	// A move from a state no move of this command starts from is the wrong-state answer, whichever
	// guarded branch or default made it (entity-core `admit_state`); a branch that moves nothing
	// answers in every state. That includes an eligible external branch: Entity Runtime sorts it
	// ahead of the default, so an arranged one answers here, and the draw offers it beside the
	// wrong-state answer. Where the subject is stranded, only externals that move nothing are
	// eligible (exploreEligible drops a move from a state it does not start from).
	stranded := record != nil && moves > 0 && !starts[fmt.Sprint(record.fields["state"])]
	wrongState := func() exploreDecision {
		if wrong != nil {
			externals, unknown := exploreEligible(command, outcomes, source, record)
			if unknown != "" {
				return exploreDecision{kind: "unknown", reason: unknown}
			}
			return exploreDecision{kind: "take", outcome: wrong, externals: externals}
		}
		return orExternal(exploreDecision{kind: "ambiguous", names: []string{fmt.Sprintf("no outcome for state %v", record.fields["state"])}})
	}

	// The held row (beyond10x/ess#221): the branches selected by the stored row — its held state, a
	// stored field, a predicate over its fields — whose input guard holds too, before every
	// accepting guard (the precedence order, step 4), the first declared that holds answering. An
	// accepting guard declared before it that holds as well is the one branch the interpreter
	// (`interpret::execute::select`, declaration order) and the precedence order answer
	// differently, so that draw alone the specification does not decide, and it is redrawn.
	held, undecided := exploreHeld(command, outcomes, record, source, input)
	if undecided != nil {
		return *undecided
	}
	holding := []map[string]any{}
	if held != nil {
		earlier := []string{}
		for _, outcome := range outcomes {
			if fmt.Sprint(outcome["name"]) == fmt.Sprint(held["name"]) {
				break
			}
			if exploreObject(outcome["condition"])["kind"] != "when" || exploreIsInputRefusal(outcome) {
				continue
			}
			guard := command.guards[fmt.Sprint(outcome["name"])]
			switch guard.evaluate(source) {
			case truthUnknown:
				return exploreDecision{kind: "unknown", reason: fmt.Sprintf("the guard of `%v` (%s) is unknown over a generated input", outcome["name"], guard)}
			case truthTrue:
				earlier = append(earlier, fmt.Sprint(outcome["name"]))
			}
		}
		if len(earlier) > 0 {
			return orExternal(exploreDecision{kind: "ambiguous", names: append(earlier, fmt.Sprint(held["name"]))})
		}
		holding = append(holding, held)
	}
	for _, outcome := range outcomes {
		if held != nil || exploreObject(outcome["condition"])["kind"] != "when" || exploreIsInputRefusal(outcome) {
			continue
		}
		guard := command.guards[fmt.Sprint(outcome["name"])]
		switch guard.evaluate(source) {
		case truthUnknown:
			return exploreDecision{kind: "unknown", reason: fmt.Sprintf("the guard of `%v` (%s) is unknown over a generated input", outcome["name"], guard)}
		case truthTrue:
			holding = append(holding, outcome)
		}
	}
	// The external branches this input and subject make eligible. Their guards state eligibility,
	// not the verdict, so they take no part in choosing the ordinary branch; and where no ordinary
	// branch can be taken, they still can.
	externals, unknown := exploreEligible(command, outcomes, source, record)
	if unknown != "" {
		return exploreDecision{kind: "unknown", reason: unknown}
	}
	var selected map[string]any
	switch {
	case len(holding) > 1:
		// Where every branch that holds moves and the subject rests where no move starts, each
		// of them is the wrong-state answer, so the overlap decides nothing.
		if stranded && exploreAllMove(holding) {
			return wrongState()
		}
		names := []string{}
		for _, outcome := range holding {
			names = append(names, fmt.Sprint(outcome["name"]))
		}
		return orExternal(exploreDecision{kind: "ambiguous", names: names})
	case len(holding) == 1:
		selected = holding[0]
	default:
		for _, outcome := range outcomes {
			if exploreObject(outcome["condition"])["kind"] == "otherwise" {
				selected = outcome
				break
			}
		}
		if selected == nil {
			return orExternal(exploreDecision{kind: "ambiguous", names: []string{"no outcome holds"}})
		}
	}
	if exploreObject(selected["subject"])["effect"] == "moves" && record != nil &&
		!exploreContains(exploreFrom(selected), fmt.Sprint(record.fields["state"])) {
		if stranded {
			return wrongState()
		}
		names := []string{fmt.Sprint(selected["name"])}
		if wrong != nil {
			names = append(names, fmt.Sprint(wrong["name"]))
		}
		return orExternal(exploreDecision{kind: "ambiguous", names: names})
	}
	return exploreDecision{kind: "take", outcome: exploreTerminal(command, selected, input, model), externals: externals}
}

// exploreRowHolds is whether a branch selected by the stored row holds for record and this input,
// or the decision a guard the model cannot evaluate stands for: `unknown` where a path of the
// input is missing, which is so for every draw of that input, and `undetermined` where a stored
// field is unset or null, which another record need not share.
func exploreRowHolds(command *exploreCommand, name string, row exploreRowGuard, record *exploreRecord, source factSource, input Row) (bool, *exploreDecision) {
	stored := truthTrue
	unread := exploreUnread{}
	switch row.kind {
	case "subject_state", "state_change":
		stored = truthOf(row.states[fmt.Sprint(record.fields["state"])])
	case "subject_field":
		value, ok := record.fields[row.field]
		switch {
		case !ok:
			stored, unread = truthUnknown, exploreUnread{path: row.field}
		case value == nil:
			stored, unread = truthUnknown, exploreUnread{path: row.field, null: true}
		default:
			stored = truthOf(equal(value, row.equals))
		}
	case "subject_predicate":
		combined := Row{}
		for field, value := range record.fields {
			combined[field] = value
		}
		combined["input"] = map[string]any(input)
		stored = row.stored.evaluate(facts(combined))
		if stored == truthUnknown {
			unread = exploreUnreadIn(*row.stored, combined)
		}
	}
	if stored == truthFalse {
		return false, nil
	}
	guard := truthTrue
	if row.input != nil {
		guard = row.input.evaluate(source)
		if guard == truthUnknown {
			return false, &exploreDecision{kind: "unknown", reason: fmt.Sprintf("the guard of `%s` (%s) is unknown over a generated input", name, *row.input)}
		}
	}
	if unread.input {
		return false, &exploreDecision{kind: "unknown", reason: fmt.Sprintf("the guard of `%s` (%s) is unknown over a generated input", name, *row.stored)}
	}
	if guard == truthFalse {
		return false, nil
	}
	if stored == truthUnknown {
		why := "which no command set"
		if unread.null {
			why = "which the row holds as null"
		}
		return false, &exploreDecision{kind: "undetermined", reason: fmt.Sprintf("%s guard of `%s` reads %s, %s", command.name, name, unread.path, why)}
	}
	return true, nil
}

// exploreUnread is the path that left a stored-row predicate Unknown: a path of the input under
// `input.` the draw does not hold, or else a stored field the row does not hold or holds as null.
type exploreUnread struct {
	path  string
	input bool
	null  bool
}

// exploreUnreadIn is what left p Unknown over row: the input is blamed only where one of its paths
// is actually missing (beyond10x/ess#221 adversary pass 1).
func exploreUnreadIn(p predicate, row Row) exploreUnread {
	source := facts(row)
	paths := explorePaths(p)
	for _, path := range paths {
		if strings.HasPrefix(path, "input.") && !present(source, path) {
			return exploreUnread{path: path, input: true}
		}
	}
	for _, path := range paths {
		if strings.HasPrefix(path, "input.") || present(source, path) {
			continue
		}
		_, bound := source[path]
		return exploreUnread{path: path, null: bound}
	}
	if len(paths) > 0 {
		return exploreUnread{path: paths[0]}
	}
	return exploreUnread{}
}

// exploreHeld is the first branch selected by the stored row that holds, in declaration order, or
// the decision a branch the model cannot evaluate before it stands for. A branch after the one
// that holds is not read, as `interpret::execute::select` stops at the first that holds.
func exploreHeld(command *exploreCommand, outcomes []map[string]any, record *exploreRecord, source factSource, input Row) (map[string]any, *exploreDecision) {
	for _, outcome := range outcomes {
		name := fmt.Sprint(outcome["name"])
		row, ok := command.rows[name]
		if !ok {
			continue
		}
		holds, undecided := exploreRowHolds(command, name, row, record, source, input)
		if undecided != nil {
			return nil, undecided
		}
		if holds {
			return outcome, nil
		}
	}
	return nil, nil
}

// exploreEligible is the external branches of a command this input and subject make eligible, in
// declaration order, or why an eligibility guard cannot be evaluated.
func exploreEligible(command *exploreCommand, outcomes []map[string]any, source factSource, record *exploreRecord) ([]map[string]any, string) {
	externals := []map[string]any{}
	for _, outcome := range outcomes {
		if !exploreIsExternal(outcome) {
			continue
		}
		if exploreObject(outcome["condition"])["kind"] == "external_when" {
			guard := command.guards[fmt.Sprint(outcome["name"])]
			truth := guard.evaluate(source)
			if truth == truthUnknown {
				return nil, fmt.Sprintf("the guard of `%v` (%s) is unknown over a generated input", outcome["name"], guard)
			}
			if truth != truthTrue {
				continue
			}
		}
		if exploreObject(outcome["subject"])["effect"] == "moves" && record != nil &&
			!exploreContains(exploreFrom(outcome), fmt.Sprint(record.fields["state"])) {
			continue
		}
		externals = append(externals, outcome)
	}
	return externals, ""
}

// exploreChoices is the branches a step may take: the ordinary one, unless an earlier arrangement
// of this command may still hold and an external branch is eligible, then every eligible external
// branch the target has not refused to arrange.
type exploreChoice struct {
	arrangement string
	expected    map[string]any
}

func exploreChoices(s *exploreSession, command *exploreCommand, decision exploreDecision, input Row) []exploreChoice {
	choices := []exploreChoice{}
	if decision.outcome != nil && (!s.forced[command.name] || len(decision.externals) == 0) {
		choices = append(choices, exploreChoice{expected: decision.outcome})
	}
	for _, outcome := range decision.externals {
		if _, refused := s.p.unarrangeable[command.name+"/"+fmt.Sprint(outcome["name"])]; !refused {
			choices = append(choices, exploreChoice{arrangement: fmt.Sprint(outcome["name"]), expected: exploreTerminal(command, outcome, input, s.model)})
		}
	}
	return choices
}

// exploreArrange asks the target to make command take the external branch outcome.
func exploreArrange(s *exploreSession, command *exploreCommand, outcome string) (*exploreDisagreement, *exploreUnsupported) {
	err := s.target.ConfigureExternalOutcome(ExternalOutcomeControl{
		Command: command.name, Outcome: outcome, Correlation: s.correlation,
	})
	if err != nil {
		if errors.Is(err, ErrUnsupported) {
			return nil, &exploreUnsupported{reason: err.Error()}
		}
		return &exploreDisagreement{kind: "target", detail: fmt.Sprintf("arranging `%s`, the target threw %s", outcome, err.Error())}, nil
	}
	s.forced[command.name] = true
	return nil, nil
}

// ---- drawing inputs -----------------------------------------------------------------------------

type exploreRef struct {
	path   string
	entity string
	index  int
}

// exploreStep is one step of a trace. An input naming an existing record keeps it as (entity,
// creation index), so a shorter trace re-resolves it.
type exploreStep struct {
	command string
	input   Row
	refs    []exploreRef
	// external is the external branch arranged for this step, or empty for the ordinary branch.
	external string
	fresh    []exploreRef
	// restart marks a restart of the target rather than a command.
	restart bool
}

var errExploreNoRecord = errors.New("no record")

type exploreAbsentValue struct{}

var exploreAbsent = exploreAbsentValue{}

func exploreDraw(kind exploreKind, r *Mulberry32, command *exploreCommand, model *exploreModel, path string, mustExist bool, refs *[]exploreRef) (Node, error) {
	switch kind.kind {
	case "optional":
		if r.Chance(0.5) {
			return exploreAbsent, nil
		}
		return exploreDraw(*kind.base, r, command, model, path, mustExist, refs)
	case "identity":
		known := model.of(kind.entity)
		if mustExist {
			if len(known) == 0 {
				return nil, errExploreNoRecord
			}
			index := r.Int(0, len(known)-1)
			*refs = append(*refs, exploreRef{path: path, entity: kind.entity, index: index})
			return known[index].id, nil
		}
		if len(known) > 0 && r.Chance(0.8) {
			index := r.Int(0, len(known)-1)
			*refs = append(*refs, exploreRef{path: path, entity: kind.entity, index: index})
			return known[index].id, nil
		}
		return exploreDraw(*kind.base, r, command, model, path, false, refs)
	case "integer", "decimal":
		if r.Chance(0.7) {
			return explorePick(r, command.pools.integersAt(path)), nil
		}
		return float64(r.Int(-10, 10000)), nil
	case "boolean":
		return r.Chance(0.5), nil
	case "string":
		return explorePick(r, command.pools.textsAt(path)), nil
	case "timestamp":
		// One seeded draw selects a UTC second on a fixed date, never a target clock.
		second := r.Int(0, 86399)
		return fmt.Sprintf("2020-01-01T%02d:%02d:%02dZ", second/3600, second/60%60, second%60), nil
	case "uuid":
		return fmt.Sprintf("00000000-0000-4000-8000-%012d", r.Int(0, 999999)), nil
	case "enum":
		return explorePick(r, command.pools.enumsAt(path, kind.variants)), nil
	case "struct":
		value := map[string]any{}
		for _, field := range kind.fields {
			drawn, err := exploreDraw(field.kind, r, command, model, path+"."+field.name, false, refs)
			if err != nil {
				return nil, err
			}
			if _, absent := drawn.(exploreAbsentValue); !absent {
				value[field.name] = drawn
			} else if field.presence != "omitted_when_absent" {
				value[field.name] = nil
			}
		}
		return value, nil
	default:
		return nil, nil
	}
}

func exploreDrawStep(command *exploreCommand, r *Mulberry32, model *exploreModel) *exploreStep {
	supplied := exploreSupplied(command)
	instance := ""
	entity := ""
	if supplied != nil {
		subject := exploreObject(supplied["subject"])
		instance = exploreString(exploreObject(exploreObject(subject["instance"])["field"])["name"])
		entity = exploreString(subject["entity"])
	}
	// created is the input naming the identity an `existing_instance` branch is decided by, and
	// the entity it is looked up in (beyond10x/ess#221): drawn, as a supplied instance with an
	// unknown-instance branch is, to name a record or not with even chance.
	created, createdEntity := "", ""
	if exploreExistingIn(command.node) != nil {
		for _, address := range exploreAddresses(command.node) {
			if address.field != "" {
				created, createdEntity = address.field, address.entity
			}
		}
	}
	input := Row{}
	refs := []exploreRef{}
	fresh := []exploreRef{}
	for _, field := range command.inputs {
		kind := field.kind
		if field.name == instance && kind.kind != "identity" {
			base := kind
			kind = exploreKind{kind: "identity", entity: entity, base: &base}
		}
		probed := entity
		if field.name == created && !(field.name == instance && exploreUnknown(command) != nil) {
			base := kind
			if kind.kind == "identity" {
				base = *kind.base
			}
			kind = exploreKind{kind: "identity", entity: createdEntity, base: &base}
			probed = createdEntity
		}
		var value Node
		var err error
		if (field.name == instance && exploreUnknown(command) != nil) || field.name == created {
			if len(model.of(probed)) > 0 && r.Chance(0.5) {
				value, err = exploreDraw(kind, r, command, model, field.name, true, &refs)
			} else {
				base := kind
				if kind.kind == "identity" {
					base = *kind.base
				}
				err = errExploreNoRecord
				for attempt := 0; attempt < exploreAttempts; attempt++ {
					ignored := []exploreRef{}
					drawn, problem := exploreDraw(base, r, command, model, field.name, false, &ignored)
					_, absent := drawn.(exploreAbsentValue)
					if problem == nil && !absent && model.find(probed, drawn) == nil {
						value, err = drawn, nil
						fresh = append(fresh, exploreRef{path: field.name, entity: probed})
						break
					}
				}
			}
		} else {
			value, err = exploreDraw(kind, r, command, model, field.name, field.name == instance, &refs)
		}
		if err != nil {
			return nil
		}
		if _, absent := value.(exploreAbsentValue); !absent {
			input[field.name] = value
		} else if field.presence != "omitted_when_absent" {
			input[field.name] = nil
		}
	}
	return &exploreStep{command: command.name, input: input, refs: refs, fresh: fresh}
}

// ---- one step against the target ----------------------------------------------------------------

type exploreDisagreement struct {
	kind   string
	detail string
}

type exploreUnsupported struct {
	reason string
}

type exploreSession struct {
	p            *explorePlan
	target       Target
	model        *exploreModel
	correlation  string
	scenario     string
	undetermined map[string]bool
	// forced is every command the target was asked to arrange a branch for in this sequence.
	forced map[string]bool
	// token is the consistency token the last command returned.
	token string
}

func exploreRender(value Node, determined bool) string {
	if !determined {
		return "nothing"
	}
	bytes, err := json.Marshal(value)
	if err != nil {
		return fmt.Sprint(value)
	}
	return string(bytes)
}

func explorePerform(s *exploreSession, command *exploreCommand, step *exploreStep, outcome map[string]any) (*exploreDisagreement, *exploreUnsupported) {
	ir := s.p.ir
	result, err := s.target.ExecuteCommand(CommandRequest{
		Command: command.name, Actor: command.actor, Input: map[string]Node(step.input), Correlation: s.correlation,
	})
	if err != nil {
		if errors.Is(err, ErrUnsupported) {
			return nil, &exploreUnsupported{reason: err.Error()}
		}
		return &exploreDisagreement{kind: "target", detail: "the target threw " + err.Error()}, nil
	}
	s.token = result.Consistency
	name := fmt.Sprint(outcome["name"])
	if result.Outcome != name {
		return &exploreDisagreement{kind: "outcome", detail: fmt.Sprintf("the target answered `%s`, the specification says `%s`", result.Outcome, name)}, nil
	}
	wanted := exploreString(outcome["error"])
	if result.Error != wanted {
		return &exploreDisagreement{kind: "error", detail: fmt.Sprintf("the target refused with `%s`, the specification says `%s`", result.Error, wanted)}, nil
	}
	names := []string{}
	for _, event := range result.DirectEvents {
		names = append(names, event.Event)
	}
	emits := exploreStrings(outcome["emits"])
	if strings.Join(names, ", ") != strings.Join(emits, ", ") {
		return &exploreDisagreement{kind: "events", detail: fmt.Sprintf("the target emitted [%s], the specification says [%s]", strings.Join(names, ", "), strings.Join(emits, ", "))}, nil
	}
	for index, event := range result.DirectEvents {
		var declared map[string]any
		for _, entry := range exploreList(outcome["payload"]) {
			if exploreObject(entry)["event"] == event.Event {
				declared = exploreObject(entry)
				break
			}
		}
		for _, field := range exploreList(declared["fields"]) {
			field := exploreObject(field)
			expected, state := exploreValue(ir, exploreObject(field["value"]), step.input, exploreObject(field["target_type"]))
			if state != exploreDetermined {
				continue
			}
			target := exploreString(field["target"])
			actual, present := event.Payload[target]
			var naming map[string]any
			for _, item := range exploreList(exploreObject(exploreObject(ir["events"])[event.Event])["fields"]) {
				declared := exploreObject(item)
				if declared["name"] == target {
					naming = exploreObject(declared["naming"])
				}
			}
			if !exploreValueAgrees(ir, exploreObject(field["target_type"]), naming, expected, actual, present, 0) {
				return &exploreDisagreement{kind: "payload", detail: fmt.Sprintf("event %d `%s`.%s is %s, the specification says %s", index, event.Event, target, exploreRender(actual, present), exploreRender(expected, true))}, nil
			}
		}
	}

	subject := exploreObject(outcome["subject"])
	if subject != nil {
		entityName := exploreString(subject["entity"])
		entity := exploreObject(exploreObject(ir["entities"])[entityName])
		instance := exploreObject(subject["instance"])
		field := exploreString(exploreObject(instance["field"])["name"])
		var record *exploreRecord
		if subject["effect"] == "creates" {
			carrier := exploreString(instance["event"])
			var id Node
			for _, event := range result.DirectEvents {
				if event.Event == carrier {
					id = event.Payload[field]
					break
				}
			}
			if id == nil {
				return &exploreDisagreement{kind: "identity", detail: fmt.Sprintf("the target emitted no `%s`.%s", carrier, field)}, nil
			}
			if s.model.find(entityName, id) != nil {
				return &exploreDisagreement{kind: "identity", detail: fmt.Sprintf("the target created %s again, over an existing record", exploreRender(id, true))}, nil
			}
			identity := exploreString(exploreObject(entity["identity"])["name"])
			// A creation lands in the state `into:` names (ess/15), or where the lifecycle starts.
			state := exploreObject(entity["lifecycle"])["initial"]
			if into, ok := subject["into"]; ok && into != nil {
				state = into
			}
			record = &exploreRecord{id: id, fields: Row{identity: id, "state": state}}
			s.model.records[entityName] = append(s.model.records[entityName], record)
		} else {
			id, _ := exploreReadPath(map[string]any(step.input), field)
			record = s.model.find(entityName, id)
			if record != nil && subject["effect"] == "moves" {
				record.fields["state"] = exploreObject(subject["transition"])["to"]
			}
		}
		if record != nil {
			for _, set := range exploreList(outcome["sets"]) {
				set := exploreObject(set)
				value, state := exploreValue(ir, exploreObject(set["value"]), step.input, exploreObject(set["target_type"]))
				target := exploreString(set["target"])
				if state == exploreDetermined {
					record.fields[target] = value
				} else if state == exploreCleared {
					record.fields[target] = nil
				} else {
					delete(record.fields, target)
				}
			}
		}
	}

	if found := exploreViews(s, result.Consistency); found != nil {
		return found, nil
	}
	return exploreInvariants(s), nil
}

func exploreAgree(ir, view map[string]any, identity string, rows []Row, expected []*exploreRecord) *exploreDisagreement {
	name := exploreString(view["name"])
	if len(rows) != len(expected) {
		return &exploreDisagreement{kind: "view-rows", detail: fmt.Sprintf("`%s` holds %d row(s), the specification says %d", name, len(rows), len(expected))}
	}
	fields := []string{}
	for _, field := range exploreList(view["fields"]) {
		fields = append(fields, fmt.Sprint(exploreObject(field)["name"]))
	}
	if exploreContains(fields, identity) {
		seen := map[*exploreRecord]bool{}
		for _, row := range rows {
			var record *exploreRecord
			for _, candidate := range expected {
				if equal(candidate.id, row[identity]) {
					record = candidate
					break
				}
			}
			if record == nil || seen[record] {
				value, present := row[identity]
				return &exploreDisagreement{kind: "view-rows", detail: fmt.Sprintf("`%s` holds %s %s, which the specification does not place there", name, identity, exploreRender(value, present))}
			}
			seen[record] = true
			for _, field := range fields {
				want, ok := record.fields[field]
				if !ok {
					continue
				}
				got, present := row[field]
				var declared map[string]any
				for _, item := range exploreList(view["fields"]) {
					candidate := exploreObject(item)
					if candidate["name"] == field {
						declared = candidate
						break
					}
				}
				if !exploreValueAgrees(ir, exploreObject(declared["type_ref"]), exploreObject(declared["naming"]), want, got, present, 0) {
					value, has := row[identity]
					return &exploreDisagreement{kind: "view-field", detail: fmt.Sprintf("`%s`.%s of %s is %s, the specification says %s", name, field, exploreRender(value, has), exploreRender(got, present), exploreRender(want, true))}
				}
			}
		}
	}
	orderBy := exploreStrings(view["order_by"])
	if len(orderBy) > 0 {
		if ok, message, _ := ranked(name, orderBy, rows); !ok {
			return &exploreDisagreement{kind: "view-order", detail: message}
		}
	}
	return nil
}

func exploreViews(s *exploreSession, token string) *exploreDisagreement {
	ir := s.p.ir
	views := append([]map[string]any{}, s.p.views...)
	for _, view := range views {
		name := exploreString(view["name"])
		entity := exploreObject(exploreObject(ir["entities"])[exploreString(view["source"])])
		var filter *predicate
		if view["filter"] != nil {
			parsed, _ := fromNode(view["filter"])
			filter = &parsed
		}
		expected := []*exploreRecord{}
		placed := true
		for _, record := range s.model.of(exploreString(entity["name"])) {
			if filter == nil {
				expected = append(expected, record)
				continue
			}
			truth := filter.evaluate(facts(record.fields))
			if truth == truthUnknown {
				s.undetermined[fmt.Sprintf("%s filter reads %s, which no command set", name, exploreMissing(*filter, record.fields))] = true
				placed = false
				break
			}
			if truth == truthTrue {
				expected = append(expected, record)
			}
		}
		if !placed {
			continue
		}

		eventual := view["consistency"] != "read_your_writes"
		attempts := 1
		atLeast := token
		if eventual {
			attempts = NewHarness(s.p.system).Deadline().Attempts
			atLeast = ""
		}
		var problem *exploreDisagreement
		for attempt := 0; attempt < attempts; attempt++ {
			answer, err := s.target.QueryView(ViewRequest{
				View: name, Params: map[string]Node{}, AtLeast: atLeast, Correlation: s.correlation,
				Deadline: Deadline{Attempts: attempts - attempt},
			})
			if err != nil {
				if errors.Is(err, ErrUnsupported) {
					s.p.exclude(name, "the target does not expose it: "+err.Error())
					problem = nil
					break
				}
				return &exploreDisagreement{kind: "target", detail: fmt.Sprintf("reading `%s`, the target threw %s", name, err.Error())}
			}
			problem = exploreAgree(ir, view, exploreString(exploreObject(entity["identity"])["name"]), answer.Rows, expected)
			if problem == nil {
				break
			}
		}
		if problem != nil {
			return problem
		}
	}
	return nil
}

func exploreInvariants(s *exploreSession) *exploreDisagreement {
	for _, entity := range exploreSorted(s.p.ir["entities"]) {
		name := exploreString(entity["name"])
		for _, invariant := range exploreList(entity["invariants"]) {
			p, refusal := exploreParse(invariant)
			if refusal != "" {
				continue
			}
			for _, record := range s.model.of(name) {
				switch p.evaluate(facts(record.fields)) {
				case truthFalse:
					return &exploreDisagreement{kind: "specification", detail: fmt.Sprintf("%s %s breaks `%s`: the guards allow a sequence the invariants forbid", name, exploreRender(record.id, true), p)}
				case truthUnknown:
					s.undetermined[fmt.Sprintf("%s invariant `%s` reads %s, which no command set", name, p, exploreMissing(p, record.fields))] = true
				}
			}
		}
	}
	return nil
}

// ---- sequences ----------------------------------------------------------------------------------

// exploreNoRestart is why a target without RestartTarget cannot restart.
const exploreNoRestart = "the target offers no restart"

// exploreRestart restarts the target and reads every view again. The model does not move: what the
// restarted implementation answers must be what it answered before.
func exploreRestart(s *exploreSession) (*exploreDisagreement, *exploreUnsupported) {
	restartable, ok := s.target.(RestartTarget)
	if !ok {
		return nil, &exploreUnsupported{reason: exploreNoRestart}
	}
	if err := restartable.Restart(ScenarioContext{Scenario: s.scenario, Correlation: s.correlation}); err != nil {
		if errors.Is(err, ErrUnsupported) {
			return nil, &exploreUnsupported{reason: err.Error()}
		}
		return &exploreDisagreement{kind: "target", detail: "restarting, the target threw " + err.Error()}, nil
	}
	return exploreViews(s, s.token), nil
}

func exploreLine(step *exploreStep) string {
	if step.restart {
		return "restart"
	}
	line := step.command + " " + exploreRender(map[string]Node(step.input), true)
	if step.external != "" {
		line += " [external: " + step.external + "]"
	}
	return line
}

type exploreFound struct {
	kind     string
	message  string
	executed []*exploreStep
}

func exploreHasOptional(kind exploreKind) bool {
	if kind.kind == "optional" {
		return true
	}
	if kind.base != nil && exploreHasOptional(*kind.base) {
		return true
	}
	for _, field := range kind.fields {
		if exploreHasOptional(field.kind) {
			return true
		}
	}
	return false
}

func exploreSameFailure(p *explorePlan, original, replayed *exploreFound) bool {
	if original.kind != replayed.kind {
		return false
	}
	if len(original.executed) == 0 || len(replayed.executed) == 0 {
		return false
	}
	last := original.executed[len(original.executed)-1]
	next := replayed.executed[len(replayed.executed)-1]
	strict := false
	for _, command := range p.commands {
		if command.name != last.command {
			continue
		}
		strict = exploreUnknown(command) != nil || exploreExistingIn(command.node) != nil
		for _, field := range command.inputs {
			strict = strict || exploreHasOptional(field.kind)
		}
	}
	if !strict {
		return true
	}
	if last.command != next.command || last.external != next.external || len(last.fresh) != len(next.fresh) {
		return false
	}
	for index, ref := range last.fresh {
		if ref.path != next.fresh[index].path || ref.entity != next.fresh[index].entity {
			return false
		}
	}
	return strings.Split(original.message, " (step ")[0] == strings.Split(replayed.message, " (step ")[0]
}

func exploreDescribe(found *exploreDisagreement, index int, step *exploreStep) string {
	return fmt.Sprintf("%s: %s (step %d: %s)", found.kind, found.detail, index+1, exploreLine(step))
}

func exploreOpen(p *explorePlan, newTarget func() Target, scenario string) (*exploreSession, error) {
	target := newTarget()
	correlation := NewHarness(p.system).Correlation()
	if err := target.BeginScenario(ScenarioContext{Scenario: scenario, Correlation: correlation}); err != nil {
		return nil, err
	}
	s := &exploreSession{
		p: p, target: target, model: &exploreModel{records: map[string][]*exploreRecord{}},
		correlation: correlation, scenario: scenario, undetermined: map[string]bool{}, forced: map[string]bool{},
	}
	if err := explorePreconditions(s); err != nil {
		s.close()
		return nil, err
	}
	return s, nil
}

// explorePreconditions runs the system's preconditions (ess/15) before a sequence, so the model
// starts from the state they leave. A precondition the model or the target does not take is a setup
// failure, returned as an error, and never a disagreement: the sequence has not started.
func explorePreconditions(s *exploreSession) error {
	for _, node := range exploreList(s.p.ir["preconditions"]) {
		pre := exploreObject(node)
		name := exploreString(pre["command"])
		if exploreNonEmpty(pre["fixtures"]) {
			return fmt.Errorf("precondition `%s` reads fixture inputs, which exploration does not resolve", name)
		}
		planned := s.p.command(name)
		if planned == nil {
			planned = s.p.sendable[name]
		}
		if planned == nil {
			return fmt.Errorf("precondition `%s` is a command exploration excludes", name)
		}
		command := *planned
		if actor := exploreString(pre["actor"]); actor != "" {
			command.actor = actor
		}
		input := Row{}
		for key, value := range exploreObject(pre["input"]) {
			input[key] = value
		}
		step := &exploreStep{command: name, input: input}
		decision := exploreDecide(&command, input, s.model)
		// The model must take the branch the specification requires of it, as synthesis does: a
		// precondition the model decides as a refusal, or as anything else, fails as setup.
		wanted := exploreString(pre["outcome"])
		if decision.kind != "take" || decision.outcome == nil || fmt.Sprint(decision.outcome["name"]) != wanted {
			return fmt.Errorf("precondition `%s` failed as setup: the model does not take `%s`", name, wanted)
		}
		found, unsupported := explorePerform(s, &command, step, decision.outcome)
		if unsupported != nil {
			return fmt.Errorf("precondition `%s` is not exposed by the target: %s", name, unsupported.reason)
		}
		if found != nil {
			return fmt.Errorf("precondition `%s` failed as setup: %s: %s", name, found.kind, found.detail)
		}
	}
	return nil
}

func (s *exploreSession) close() {
	_ = s.target.EndScenario(ScenarioContext{Scenario: s.scenario, Correlation: s.correlation})
}

// exploreReplay replays trace on a fresh target: the disagreement it ends in, or nil when it
// passes.
func exploreReplay(p *explorePlan, newTarget func() Target, trace []*exploreStep, scenario string) (*exploreFound, error) {
	s, err := exploreOpen(p, newTarget, scenario)
	if err != nil {
		return nil, err
	}
	defer s.close()
	executed := []*exploreStep{}
	for _, recorded := range trace {
		if recorded.restart {
			found, unsupported := exploreRestart(s)
			if unsupported != nil {
				continue
			}
			executed = append(executed, recorded)
			if found != nil {
				return &exploreFound{kind: found.kind, message: exploreDescribe(found, len(executed)-1, recorded), executed: executed}, nil
			}
			continue
		}
		command := p.command(recorded.command)
		if command == nil {
			continue
		}
		input := exploreCopy(map[string]any(recorded.input)).(map[string]any)
		resolvable := true
		for _, ref := range recorded.refs {
			known := s.model.of(ref.entity)
			if ref.index >= len(known) {
				resolvable = false
			} else {
				exploreSetPath(input, ref.path, known[ref.index].id)
			}
		}
		if !resolvable {
			continue
		}
		for _, ref := range recorded.fresh {
			id, _ := exploreReadPath(input, ref.path)
			if s.model.find(ref.entity, id) != nil {
				resolvable = false
			}
		}
		if !resolvable {
			continue
		}
		step := &exploreStep{command: recorded.command, input: Row(input), refs: recorded.refs, external: recorded.external, fresh: recorded.fresh}
		decision := exploreDecide(command, step.input, s.model)
		if decision.kind != "take" {
			continue
		}
		var outcome map[string]any
		for _, choice := range exploreChoices(s, command, decision, step.input) {
			if choice.arrangement == step.external {
				outcome = choice.expected
				break
			}
		}
		if outcome == nil {
			continue
		}
		if step.external != "" {
			found, unsupported := exploreArrange(s, command, step.external)
			if unsupported != nil {
				continue
			}
			if found != nil {
				executed = append(executed, step)
				return &exploreFound{kind: found.kind, message: exploreDescribe(found, len(executed)-1, step), executed: executed}, nil
			}
		}
		found, unsupported := explorePerform(s, command, step, outcome)
		if unsupported != nil {
			continue
		}
		executed = append(executed, step)
		if found != nil {
			return &exploreFound{kind: found.kind, message: exploreDescribe(found, len(executed)-1, step), executed: executed}, nil
		}
	}
	return nil, nil
}

// Explore runs Seeds sequences of Steps random commands, each on a fresh target, and checks every
// step against the model interpreted from `ir.json`. It stops at the first disagreement and
// shrinks it.
//
// It returns an error only when the model cannot be used: an unreadable `ir.json`, or one that is
// not the model `suite.json` was synthesized from. A disagreement is the result's Failure.
func Explore(newTarget func() Target, options ExploreOptions) (ExploreResult, error) {
	ir, err := exploreLoad(exploreIR, exploreSuite)
	if err != nil {
		return ExploreResult{}, err
	}
	every := options.RestartEvery
	if every < 0 {
		return ExploreResult{}, errors.New("the restart interval must be a whole number of steps, zero or more")
	}
	p := explorePlanOf(ir)
	steps := options.Steps
	if steps == 0 {
		steps = exploreDefaultSteps
	}
	seeds := []int{}
	if options.Seed != 0 {
		seeds = append(seeds, options.Seed)
	} else {
		count := options.Seeds
		if count == 0 {
			count = exploreDefaultSeeds
		}
		for seed := 1; seed <= count; seed++ {
			seeds = append(seeds, seed)
		}
	}

	reached := map[string]bool{}
	ambiguous := map[string]bool{}
	undetermined := map[string]bool{}
	executed := 0
	sequences := 0
	var failure *ExploreFailure
	// performed counts the restarts a command followed; refused is why the target cannot restart,
	// and stops every later restart.
	performed := 0
	refused := ""

	for _, seed := range seeds {
		if len(p.commands) == 0 || failure != nil {
			break
		}
		sequences++
		r := NewMulberry32(uint32(seed))
		s, err := exploreOpen(p, newTarget, fmt.Sprintf("explore/seed-%d", seed))
		if err != nil {
			return ExploreResult{}, err
		}
		s.undetermined = undetermined
		trace := []*exploreStep{}
		// restarts is the number of restart steps in trace, which are not commands; pending is the
		// number of them no command has followed yet. A restart is a check only once a command has
		// followed it, so one after the last command is followed by one more.
		restarts := 0
		pending := 0
		var found *exploreFound
		for attempts := 0; (len(trace)-restarts < steps || pending > 0) && attempts < steps*exploreAttempts; attempts++ {
			if len(p.commands) == 0 {
				break
			}
			command := explorePick(r, p.commands)
			step := exploreDrawStep(command, r, s.model)
			if step == nil {
				continue
			}
			decision := exploreDecide(command, step.input, s.model)
			if decision.kind == "ambiguous" {
				ambiguous[command.name+": "+strings.Join(decision.names, ", ")] = true
				continue
			}
			if decision.kind == "unknown" {
				p.exclude(command.name, decision.reason)
				continue
			}
			if decision.kind == "undetermined" {
				undetermined[decision.reason] = true
				continue
			}
			choices := exploreChoices(s, command, decision, step.input)
			if len(choices) == 0 {
				if len(decision.names) > 0 {
					ambiguous[command.name+": "+strings.Join(decision.names, ", ")] = true
				}
				continue
			}
			outcome := choices[0]
			if len(choices) > 1 {
				outcome = explorePick(r, choices)
			}
			if outcome.arrangement != "" {
				step.external = outcome.arrangement
				arranging, unsupported := exploreArrange(s, command, step.external)
				if unsupported != nil {
					p.unarrangeable[command.name+"/"+step.external] = "the target cannot arrange it: " + unsupported.reason
					continue
				}
				if arranging != nil {
					trace = append(trace, step)
					found = &exploreFound{kind: arranging.kind, message: exploreDescribe(arranging, len(trace)-1, step), executed: append([]*exploreStep{}, trace...)}
					break
				}
			}
			disagreement, unsupported := explorePerform(s, command, step, outcome.expected)
			if unsupported != nil {
				p.exclude(command.name, "the target does not expose it: "+unsupported.reason)
				continue
			}
			executed++
			trace = append(trace, step)
			performed += pending
			pending = 0
			reached[command.name+"/"+fmt.Sprint(outcome.expected["name"])] = true
			if disagreement != nil {
				found = &exploreFound{kind: disagreement.kind, message: exploreDescribe(disagreement, len(trace)-1, step), executed: append([]*exploreStep{}, trace...)}
				break
			}
			// No restart after the command that follows the last scheduled one.
			if commands := len(trace) - restarts; every == 0 || refused != "" || commands%every != 0 || commands > steps {
				continue
			}
			restart := &exploreStep{restart: true}
			disagreement, unsupported = exploreRestart(s)
			if unsupported != nil {
				refused = unsupported.reason
				continue
			}
			pending++
			restarts++
			trace = append(trace, restart)
			if disagreement != nil {
				found = &exploreFound{kind: disagreement.kind, message: exploreDescribe(disagreement, len(trace)-1, restart), executed: append([]*exploreStep{}, trace...)}
				break
			}
		}
		s.close()
		if found != nil {
			failure, err = exploreShrink(p, newTarget, seed, trace, found)
			if err != nil {
				return ExploreResult{}, err
			}
		}
	}

	unreached := map[string]bool{}
	excludedOutcomes := map[string]bool{}
	for _, declared := range p.declared {
		for _, outcome := range declared.outcomes {
			id := declared.command + "/" + outcome
			if p.excludedCommands[declared.command] {
				excludedOutcomes[id] = true
			} else if _, refused := p.unarrangeable[id]; !reached[id] && !refused {
				unreached[id] = true
			}
		}
	}
	external := []ExternalReach{}
	for _, branch := range p.externals {
		reach := ExternalReach{Outcome: branch.id, Cause: branch.cause, Reach: "unreached"}
		reason, refused := p.unarrangeable[branch.id]
		switch {
		case p.excludedCommands[branch.command]:
			reach.Reach = "excluded"
		case reached[branch.id]:
			reach.Reach = "reached"
		case refused:
			reach.Reach = "unarrangeable"
			reach.Reason = reason
		}
		external = append(external, reach)
	}
	sort.SliceStable(external, func(i, j int) bool { return external[i].Outcome < external[j].Outcome })
	excluded := append([]Exclusion{}, p.excluded...)
	sort.SliceStable(excluded, func(i, j int) bool {
		if excluded[i].Subject != excluded[j].Subject {
			return excluded[i].Subject < excluded[j].Subject
		}
		return excluded[i].Reason < excluded[j].Reason
	})
	var restarts *RestartReach
	if every > 0 {
		restarts = &RestartReach{Every: every, Performed: performed, Unsupported: refused}
	}
	return ExploreResult{
		Sequences:        sequences,
		Steps:            steps,
		Executed:         executed,
		Reached:          exploreSet(reached),
		Unreached:        exploreSet(unreached),
		Excluded:         excluded,
		ExcludedOutcomes: exploreSet(excludedOutcomes),
		Undetermined:     exploreSet(undetermined),
		Ambiguous:        exploreSet(ambiguous),
		External:         external,
		Restarts:         restarts,
		Failure:          failure,
	}, nil
}

// exploreShrink removes one step at a time, last to first, while the shorter trace still fails the
// same way.
func exploreShrink(p *explorePlan, newTarget func() Target, seed int, trace []*exploreStep, found *exploreFound) (*ExploreFailure, error) {
	current := trace
	shortest := found
	replays := 0
	complete := true
	for removed := true; removed; {
		removed = false
		for index := len(current) - 1; index >= 0; index-- {
			if replays >= exploreShrinks {
				complete = false
				break
			}
			candidate := make([]*exploreStep, 0, len(current)-1)
			candidate = append(candidate, current[:index]...)
			candidate = append(candidate, current[index+1:]...)
			replays++
			again, err := exploreReplay(p, newTarget, candidate, fmt.Sprintf("explore/seed-%d/shrink-%d", seed, replays))
			if err != nil {
				return nil, err
			}
			if again != nil && exploreSameFailure(p, found, again) {
				current = candidate
				shortest = again
				removed = true
			}
		}
		if !complete {
			break
		}
	}
	lines := []string{}
	for _, step := range shortest.executed {
		lines = append(lines, exploreLine(step))
	}
	return &ExploreFailure{Seed: seed, Message: shortest.message, Trace: lines, OriginalLength: len(trace), ShrinkComplete: complete}, nil
}

// CheckExplored is what AssertExplored would fail with, or nil when it passes.
func CheckExplored(result ExploreResult, options AssertOptions) error {
	problems := []string{}
	if failure := result.Failure; failure != nil {
		minimal := ""
		if !failure.ShrinkComplete {
			minimal = ", not minimal"
		}
		steps := []string{}
		for _, step := range failure.Trace {
			steps = append(steps, "  "+step)
		}
		problems = append(problems, fmt.Sprintf("explore: seed %d: %s\nshrunk trace (%d of %d step(s)%s):\n%s", failure.Seed, failure.Message, len(failure.Trace), failure.OriginalLength, minimal, strings.Join(steps, "\n")))
	}
	if len(result.Unreached) > 0 {
		lines := []string{}
		for _, outcome := range result.Unreached {
			lines = append(lines, "  "+outcome)
		}
		problems = append(problems, fmt.Sprintf("explore: %d declared outcome(s) no sequence reached:\n%s", len(result.Unreached), strings.Join(lines, "\n")))
	}
	if len(result.ExcludedOutcomes) > 0 && !options.AllowExcluded {
		lines := []string{}
		for _, outcome := range result.ExcludedOutcomes {
			lines = append(lines, "  "+outcome)
		}
		reasons := []string{}
		for _, exclusion := range result.Excluded {
			reasons = append(reasons, fmt.Sprintf("  %s: %s", exclusion.Subject, exclusion.Reason))
		}
		problems = append(problems, fmt.Sprintf("explore: %d declared outcome(s) of excluded commands were never tried:\n%s\nexcluded:\n%s\naccept them explicitly with AssertOptions{AllowExcluded: true}", len(result.ExcludedOutcomes), strings.Join(lines, "\n"), strings.Join(reasons, "\n")))
	}
	unarrangeable := []string{}
	for _, branch := range result.External {
		if branch.Reach == "unarrangeable" {
			unarrangeable = append(unarrangeable, fmt.Sprintf("  %s: %s", branch.Outcome, branch.Reason))
		}
	}
	if len(unarrangeable) > 0 && !options.AllowExcluded {
		problems = append(problems, fmt.Sprintf("explore: %d external outcome(s) the target could not arrange were never tried:\n%s\naccept them explicitly with AssertOptions{AllowExcluded: true}", len(unarrangeable), strings.Join(unarrangeable, "\n")))
	}
	// Restarts asked for and not performed are never a pass, AllowExcluded or not: a caller that
	// cannot restart its target does not set RestartEvery.
	if restarts := result.Restarts; restarts != nil {
		if restarts.Unsupported != "" {
			problems = append(problems, fmt.Sprintf("explore: restarts were requested every %d step(s), and the target cannot restart: %s", restarts.Every, restarts.Unsupported))
		} else if restarts.Performed == 0 {
			problems = append(problems, fmt.Sprintf("explore: restarts were requested every %d step(s), and no sequence performed one", restarts.Every))
		}
	}
	if len(problems) == 0 {
		return nil
	}
	return errors.New(strings.Join(problems, "\n"))
}

// AssertExplored fails t when an exploration failed, when a declared outcome went unreached, or
// when an excluded command's outcomes, or external outcomes the target could not arrange, were
// never tried and AllowExcluded is not set, or when restarts were asked for and none was performed.
// What the model could not place, and the draws it would not decide, are logged and do not fail.
func AssertExplored(t testing.TB, result ExploreResult, options AssertOptions) {
	t.Helper()
	for _, note := range result.Undetermined {
		t.Logf("explore: undetermined: %s", note)
	}
	for _, note := range result.Ambiguous {
		t.Logf("explore: ambiguous: %s", note)
	}
	if err := CheckExplored(result, options); err != nil {
		t.Fatal(err)
	}
}

// ---- concurrent histories -----------------------------------------------------------------------
//
// ExploreConcurrent drives the target from two to four clients at once and writes what each call
// did as an `ess-history/1` document, one per seed. It does not decide whether a history is
// linearizable: it runs `ess verify conform check-history` on each one and reports that verdict,
// and for a violation the checker's report with its shrunk history. The checker, the model and
// the shrinking exist once, in the `ess` binary that emitted this package, so `ess` must be on
// PATH; without it concurrent exploration fails, and is never skipped.
//
// Nothing races on a wall clock. A seed draws the workload — a sequential prefix of creations on
// client 0, then a list of calls per client — and a second generator, SplitMix64 as `ess` records
// with, picks at every tick of a logical clock which client acts next: one with no call in flight
// invokes its next call, or one with a call in flight receives its answer. So one seed writes one
// history, byte for byte, and the TypeScript port writes the same bytes.
//
// A client's call may be a read of one of the specification's views, drawn from the seed beside
// the commands. A client keeps the consistency token its own last answered command returned, and
// a read of a `read_your_writes` view demands it (ViewRequest.AtLeast); a read of an `eventual`
// view demands none. The view is asked at the read's return instant, and what it answered is
// written as `rows`: the identity of each row, in the order answered, read off the field that
// carries the identity of the entity the view projects. A read's `outcome` is `read` and its
// `subject_key` is empty. A read is written without `rows`, which `ess` lists as not judged, when
// one of its rows does not carry that identity as text. For each creation of that entity invoked
// before the read returned that never answered, one row no written operation names is left out of
// `rows`, the first in answer order: it may be what that creation made, which the checker could
// only read as shown before anyone asked for it. Every other row is written and judged.
//
// With ConcurrentOptions.Inject, every fault the specification declares is injected, and no other:
// a second delivery for each `delivery: at_least_once` binding, a client retry for each command
// declaring `replays:`, and a delayed or unanswered answer for each command declaring another
// `external:` branch. Each is a move the seed schedules, drawn from its own SplitMix64 sequence of
// the seed, and ConcurrentResult.Injected counts them and the declared branches they reached.

// PendingCommand is one call between its invoke and its return.
type PendingCommand interface {
	// Complete is the answer arriving. An error that is, or wraps, ErrIndeterminate or
	// context.DeadlineExceeded is a call whose outcome is unknown: it is written `Indeterminate`,
	// because it may still have taken effect. ErrUnsupported leaves the call out of the history and
	// the command in `Excluded`. Any other error fails the exploration.
	Complete() (CommandResult, error)
}

// InterleavedTarget is a Target whose calls have an invoke and a return with other clients' calls
// in between. A Target that is not one does all of a call's work at its return instant, which is
// what an atomic call is.
type InterleavedTarget interface {
	Target
	InvokeCommand(request CommandRequest) PendingCommand
}

type exploreAtomicCall struct {
	target  Target
	request CommandRequest
}

func (c exploreAtomicCall) Complete() (CommandResult, error) {
	return c.target.ExecuteCommand(c.request)
}

// ConcurrentOptions is what one concurrent exploration is asked to do.
//
// It has no RestartEvery: restarts are sequential-only. Concurrent exploration never restarts the
// target; ExploreOptions.RestartEvery is how a sequence asks for restarts.
type ConcurrentOptions struct {
	// Path is the specification `ess` checks each history against, as `--path` takes it.
	Path string `json:"path,omitempty"`
	// Out is the directory each history is written into, as `history-<seed>.json`.
	Out string `json:"out,omitempty"`
	// Seeds is the number of histories, seeded 1…Seeds. Zero means 200.
	Seeds int `json:"seeds,omitempty"`
	// Seed, when not zero, records exactly that one history and overrides Seeds.
	Seed int `json:"seed,omitempty"`
	// Clients is how many clients call at once, 2 to 4. Zero draws it from each seed.
	Clients int `json:"clients,omitempty"`
	// Calls is how many calls each client makes after the prefix. Zero means 3.
	Calls int `json:"calls,omitempty"`
	// AllowExcluded accepts commands the target does not expose (ErrUnsupported), whose calls are
	// then not written to any history. An explicit, reviewable opt-out, as AssertOptions has.
	AllowExcluded bool `json:"allowExcluded,omitempty"`
	// Inject injects every fault the specification declares, and no other, each as one more move
	// the seed schedules: a second delivery of an event only `delivery: at_least_once` bindings
	// react to (RedeliverEvent); the same request sent again, as a second operation whose
	// `retry_of` names the first, for a command declaring `replays:`; and, for a command declaring
	// another `external:` branch, an answer delayed past the client's wait or never arriving,
	// written `Indeterminate`. Nothing is injected into the prefix. `ess` records the same way.
	Inject bool `json:"inject,omitempty"`
}

// ConcurrentInjected is what an exploration injected, keyed by what declared each fault.
type ConcurrentInjected struct {
	// Redeliveries counts second deliveries by the binding declaring `at_least_once`.
	Redeliveries map[string]int `json:"redeliveries"`
	// Refused counts second deliveries the target refused, by event.
	Refused map[string]int `json:"refused"`
	// Retries counts requests sent again, by the command declaring `replays:`.
	Retries map[string]int `json:"retries"`
	// Delayed counts calls answered after the client stopped waiting, by command.
	Delayed map[string]int `json:"delayed"`
	// Unanswered counts calls never answered and never executed, by command.
	Unanswered map[string]int `json:"unanswered"`
	// Reached counts the declared branch each retried or delayed call's answer took, as
	// `command/outcome`.
	Reached map[string]int `json:"reached"`
}

func newConcurrentInjected() ConcurrentInjected {
	return ConcurrentInjected{Redeliveries: map[string]int{}, Refused: map[string]int{}, Retries: map[string]int{}, Delayed: map[string]int{}, Unanswered: map[string]int{}, Reached: map[string]int{}}
}

func (i ConcurrentInjected) add(more ConcurrentInjected) {
	for _, pair := range [][2]map[string]int{{i.Redeliveries, more.Redeliveries}, {i.Refused, more.Refused}, {i.Retries, more.Retries}, {i.Delayed, more.Delayed}, {i.Unanswered, more.Unanswered}, {i.Reached, more.Reached}} {
		for key, count := range pair[1] {
			pair[0][key] += count
		}
	}
}

// ConcurrentFailure is the first history `ess` did not find linearizable.
type ConcurrentFailure struct {
	Seed int `json:"seed"`
	// Verdict is `Violation` or `Unknown`.
	Verdict string `json:"verdict"`
	// History is the file it was written to, inside Out.
	History string `json:"history"`
	// Report is what `ess verify conform check-history` printed: for a violation, the longest
	// partial linearization and the shrunk history.
	Report string `json:"report"`
}

// ConcurrentResult is what a concurrent exploration found.
type ConcurrentResult struct {
	Histories    int `json:"histories"`
	Linearizable int `json:"linearizable"`
	Violations   int `json:"violations"`
	Unknown      int `json:"unknown"`
	// Indeterminate is the number of calls, across every history, that never answered and were
	// written `Indeterminate`.
	Indeterminate int `json:"indeterminate"`
	// Excluded is every command or view the target answered ErrUnsupported to, and why, in the order
	// found. It is still drawn in every seed, so a seed's history does not depend on the seeds
	// before it, but its calls are not written.
	Excluded []Exclusion `json:"excluded"`
	// AllowExcluded is ConcurrentOptions.AllowExcluded, so CheckConcurrent can read it.
	AllowExcluded bool `json:"allowExcluded"`
	// Verdicts is each history's verdict, in seed order.
	Verdicts []string           `json:"verdicts"`
	Failure  *ConcurrentFailure `json:"failure,omitempty"`
	// Injected is what was injected across every history, all empty without Inject.
	Injected ConcurrentInjected `json:"injected"`
}

// ErrNoEss is the refusal when `ess` is not on PATH.
var ErrNoEss = errors.New("explore: concurrent exploration checks every history with `ess verify conform check-history`, and `ess` is not on PATH")

// ErrIndeterminate is what a target returns, or wraps, for a call whose outcome it cannot know: it
// timed out, or the connection dropped after the request left. The call is written `Indeterminate`,
// because it may still have taken effect. A context.DeadlineExceeded is read the same way. Any other
// error fails the exploration: a call that failed is not a call that may have succeeded.
var ErrIndeterminate = errors.New("the call did not answer, and may have taken effect")

const (
	exploreConcurrentSeeds  = 200
	exploreConcurrentCalls  = 3
	exploreConcurrentPrefix = 2
	exploreUndeclared       = "<undeclared>"
	// exploreInjectionStream moves the injections' SplitMix64 sequence away from the schedule's.
	exploreInjectionStream uint64 = 0x1f83d9abfb41bd6b
	exploreDelayed                = 1
	exploreUnanswered             = 2
)

// SplitMix64 is the generator that picks which client acts next, as `ess` records with.
type SplitMix64 struct {
	state uint64
}

// NewSplitMix64 starts a generator at seed.
func NewSplitMix64(seed uint64) *SplitMix64 {
	return &SplitMix64{state: seed}
}

// Next is the next 64-bit output.
func (r *SplitMix64) Next() uint64 {
	r.state += 0x9e3779b97f4a7c15
	z := r.state
	z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9
	z = (z ^ (z >> 27)) * 0x94d049bb133111eb
	return z ^ (z >> 31)
}

func (r *SplitMix64) below(bound int) int {
	return int(r.Next() % uint64(bound))
}

type exploreOperation struct {
	client     int
	command    string
	subjectKey string
	invokedAt  int
	returnedAt int
	returned   bool
	outcome    string
	// dropped is a call the target does not expose: it is not written.
	dropped bool
	// retryOf is one more than the index of the operation this one sends again, or 0.
	retryOf int
	// creates is the entity a command's creating branch creates, or empty.
	creates string
	// source is the entity a read's view projects, or empty for a command.
	source string
	// rows is what a returned read answered, each row's identity; nil where it records none.
	rows []string
}

type exploreFlight struct {
	pending PendingCommand
	command *exploreCommand
	index   int
	client  int
	// timeout is an injected delay (exploreDelayed) or loss (exploreUnanswered), or 0.
	timeout int
	// read is the request of a read, which is sent at the return instant; nil for a command.
	read *ViewRequest
	// identity is the field a read's rows carry their identity in.
	identity string
}

// exploreCall is one call of a client's workload: a command, or a read of view.
type exploreCall struct {
	command *exploreCommand
	step    *exploreStep
	view    map[string]any
}

// exploreRetry is a client's retry of the call it invoked last: waiting to be sent, then in flight.
type exploreRetry struct {
	command  *exploreCommand
	step     *exploreStep
	request  CommandRequest
	original int
	flight   *exploreFlight
}

// exploreRedelivery is an event waiting to be delivered a second time, and the bindings it reaches.
type exploreRedelivery struct {
	event    string
	bindings []string
}

type exploreRecording struct {
	target      Target
	correlation string
	clock       int
	operations  []exploreOperation
	// indeterminate counts the calls written `Indeterminate`.
	indeterminate int
	// unsupported is every command the target answered ErrUnsupported to, with its reason, in the
	// order found.
	unsupported []Exclusion
	// ir is the model, for what each binding and command declares.
	ir map[string]any
	// injection draws the injected faults, and is nil when nothing is injected.
	injection *SplitMix64
	// arranging is true while the prefix runs, when nothing is injected into a call.
	arranging    bool
	redeliveries []exploreRedelivery
	retries      []*exploreRetry
	injected     ConcurrentInjected
	// tokens is each client's last consistency token, empty until one of its commands answers one.
	tokens []string
}

// exploreKey is an identity as a subject key: its text, or empty when it is not text.
func exploreKey(value Node) string {
	text, _ := value.(string)
	return text
}

// exploreReplays is whether a command declares a `replays:` branch.
func exploreReplays(command *exploreCommand) bool {
	for _, node := range exploreList(command.node["outcomes"]) {
		if exploreObject(node)["replays"] != nil {
			return true
		}
	}
	return false
}

// exploreExternalOther is whether a command declares an `external:` branch other than a
// `replays:` one, which a retry exercises instead.
func exploreExternalOther(command *exploreCommand) bool {
	for _, node := range exploreList(command.node["outcomes"]) {
		outcome := exploreObject(node)
		if outcome["replays"] == nil && exploreIsExternal(outcome) {
			return true
		}
	}
	return false
}

func (h *exploreRecording) request(command *exploreCommand, step *exploreStep) CommandRequest {
	return CommandRequest{Command: command.name, Actor: command.actor, Input: map[string]Node(step.input), Correlation: h.correlation}
}

func (h *exploreRecording) reserve(client int, command *exploreCommand, step *exploreStep) int {
	subject := ""
	if supplied := exploreSupplied(command); supplied != nil {
		field := exploreString(exploreObject(exploreObject(exploreObject(supplied["subject"])["instance"])["field"])["name"])
		if id, ok := exploreReadPath(map[string]any(step.input), field); ok {
			subject = exploreKey(id)
		}
	}
	creates := ""
	for _, node := range exploreList(command.node["outcomes"]) {
		if subject := exploreObject(exploreObject(node)["subject"]); subject["effect"] == "creates" {
			creates = exploreString(subject["entity"])
		}
	}
	h.clock++
	index := len(h.operations)
	h.operations = append(h.operations, exploreOperation{client: client, command: command.name, subjectKey: subject, invokedAt: h.clock, creates: creates})
	return index
}

// invokeRead reserves a read of view: its request demands the client's last token where the view
// is `read_your_writes`, and is sent when the read returns.
func (h *exploreRecording) invokeRead(client int, view map[string]any) *exploreFlight {
	name := exploreString(view["name"])
	entity := exploreObject(exploreObject(h.ir["entities"])[exploreString(view["source"])])
	atLeast := ""
	if view["consistency"] == "read_your_writes" {
		atLeast = h.tokens[client]
	}
	h.clock++
	index := len(h.operations)
	h.operations = append(h.operations, exploreOperation{client: client, command: name, invokedAt: h.clock, source: exploreString(entity["name"])})
	request := ViewRequest{View: name, Params: map[string]Node{}, AtLeast: atLeast, Correlation: fmt.Sprintf("%s-%d", h.correlation, index+1), Deadline: Deadline{Attempts: 1}}
	return &exploreFlight{index: index, client: client, read: &request, identity: exploreString(exploreObject(entity["identity"])["name"])}
}

// completeRead asks the view, at the read's return instant, and writes what it answered.
func (h *exploreRecording) completeRead(flight *exploreFlight) error {
	operation := &h.operations[flight.index]
	answer, err := h.target.QueryView(*flight.read)
	h.clock++
	switch {
	case err == nil:
	case errors.Is(err, ErrUnsupported):
		operation.dropped = true
		for _, known := range h.unsupported {
			if known.Subject == operation.command {
				return nil
			}
		}
		h.unsupported = append(h.unsupported, Exclusion{Subject: operation.command, Reason: "the target does not expose it: " + err.Error()})
		return nil
	case errors.Is(err, ErrIndeterminate) || errors.Is(err, context.DeadlineExceeded):
		h.indeterminate++
		return nil
	default:
		return fmt.Errorf("reading `%s` failed: %w", operation.command, err)
	}
	operation.returned = true
	operation.returnedAt = h.clock
	operation.outcome = "read"
	rows := []string{}
	for _, row := range answer.Rows {
		id, ok := row[flight.identity].(string)
		if !ok {
			return nil
		}
		rows = append(rows, id)
	}
	operation.rows = rows
	return nil
}

// exploreWrittenRows is the rows a read is written with: every row it answered, in order, less one
// row no written operation names for each creation of the view's entity that was invoked before
// the read returned and never answered. Such a row may be the instance that creation made, which
// the checker could only read as shown before anyone asked for it; the first such rows in answer
// order are the ones left out. A named row is always written, and an unnamed row no unanswered
// creation can account for is written and is the future read it looks like.
func exploreWrittenRows(read exploreOperation, named map[string]bool, kept []exploreOperation) []string {
	lost := 0
	for _, operation := range kept {
		if !operation.returned && operation.subjectKey == "" && operation.creates == read.source && operation.invokedAt < read.returnedAt {
			lost++
		}
	}
	written := []string{}
	for _, row := range read.rows {
		if !named[row] && lost > 0 {
			lost--
			continue
		}
		written = append(written, row)
	}
	return written
}

func (h *exploreRecording) send(request CommandRequest) PendingCommand {
	var pending PendingCommand = exploreAtomicCall{target: h.target, request: request}
	if interleaved, ok := h.target.(InterleavedTarget); ok {
		pending = interleaved.InvokeCommand(request)
	}
	return pending
}

func (h *exploreRecording) invoke(client int, command *exploreCommand, step *exploreStep) *exploreFlight {
	request := h.request(command, step)
	index := h.reserve(client, command, step)
	// One call, one correlation: a retry sends it again under the same one, and a target tells a
	// retry from a new call of the same input only by it — it never replays one call for another.
	request.Correlation = fmt.Sprintf("%s-%d", h.correlation, index+1)
	timeout := 0
	if h.injection != nil && !h.arranging {
		if h.retries[client] == nil && exploreReplays(command) {
			h.retries[client] = &exploreRetry{command: command, step: step, request: request, original: index}
		}
		if exploreExternalOther(command) {
			switch h.injection.below(3) {
			case 1:
				timeout = exploreDelayed
			case 2:
				timeout = exploreUnanswered
			}
		}
	}
	return &exploreFlight{pending: h.send(request), command: command, index: index, client: client, timeout: timeout}
}

// invokeRetry sends a client's retry: the request it sent, unchanged, as a new operation.
func (h *exploreRecording) invokeRetry(client int, retry *exploreRetry) *exploreFlight {
	request := retry.request
	index := h.reserve(client, retry.command, retry.step)
	h.operations[index].retryOf = retry.original + 1
	h.injected.Retries[retry.command.name]++
	return &exploreFlight{pending: h.send(request), command: retry.command, index: index, client: client}
}

// queueRedeliveries queues a second delivery of every event result published that only
// `at_least_once` bindings react to.
func (h *exploreRecording) queueRedeliveries(result CommandResult) {
	if h.injection == nil {
		return
	}
	for _, event := range result.DirectEvents {
		bindings := []string{}
		declared := true
		for _, binding := range exploreSorted(h.ir["bindings"]) {
			if exploreString(binding["event"]) != event.Event {
				continue
			}
			bindings = append(bindings, exploreString(binding["name"]))
			declared = declared && exploreString(binding["delivery"]) == "at_least_once"
		}
		if len(bindings) > 0 && declared {
			h.redeliveries = append(h.redeliveries, exploreRedelivery{event: event.Event, bindings: bindings})
		}
	}
}

// redeliver delivers the queued event at slot a second time.
func (h *exploreRecording) redeliver(slot int) {
	queued := h.redeliveries[slot]
	h.redeliveries = append(h.redeliveries[:slot], h.redeliveries[slot+1:]...)
	if err := h.target.RedeliverEvent(RedeliveryRequest{Event: queued.event, Correlation: h.correlation}); err != nil {
		h.injected.Refused[queued.event]++
		return
	}
	for _, binding := range queued.bindings {
		h.injected.Redeliveries[binding]++
	}
}

// exploreCreated is the identity a creating branch of command published in result and its entity,
// or nil.
func exploreCreated(command *exploreCommand, result CommandResult) (Node, string) {
	for _, node := range exploreList(command.node["outcomes"]) {
		outcome := exploreObject(node)
		if fmt.Sprint(outcome["name"]) != result.Outcome {
			continue
		}
		subject := exploreObject(outcome["subject"])
		if subject["effect"] != "creates" {
			return nil, ""
		}
		instance := exploreObject(subject["instance"])
		carrier := exploreString(instance["event"])
		field := exploreString(exploreObject(instance["field"])["name"])
		for _, event := range result.DirectEvents {
			if event.Event != carrier {
				continue
			}
			id := exploreKey(event.Payload[field])
			if id == "" {
				return nil, ""
			}
			return id, exploreString(subject["entity"])
		}
		return nil, ""
	}
	return nil, ""
}

// complete writes the answer into the operation flight reserved, and returns the identity a
// creating branch published and its entity, or nil.
func (h *exploreRecording) complete(flight *exploreFlight) (Node, string, error) {
	if flight.read != nil {
		return nil, "", h.completeRead(flight)
	}
	operation := &h.operations[flight.index]
	if flight.timeout == exploreUnanswered {
		// The client stops waiting, and the target never executes the call.
		h.clock++
		h.indeterminate++
		h.injected.Unanswered[flight.command.name]++
		return nil, "", nil
	}
	result, err := flight.pending.Complete()
	h.clock++
	switch {
	case err == nil:
	case errors.Is(err, ErrUnsupported):
		operation.dropped = true
		for _, known := range h.unsupported {
			if known.Subject == flight.command.name {
				return nil, "", nil
			}
		}
		h.unsupported = append(h.unsupported, Exclusion{Subject: flight.command.name, Reason: "the target does not expose it: " + err.Error()})
		return nil, "", nil
	case errors.Is(err, ErrIndeterminate) || errors.Is(err, context.DeadlineExceeded):
		h.indeterminate++
		return nil, "", nil
	default:
		return nil, "", fmt.Errorf("`%s` failed: %w", flight.command.name, err)
	}
	h.queueRedeliveries(result)
	id, entity := exploreCreated(flight.command, result)
	if flight.timeout == exploreDelayed {
		// Executed, and answered after the client stopped waiting: written `Indeterminate`, with
		// the instance the late answer named, so a read showing it is not a read of nothing.
		h.indeterminate++
		h.injected.Delayed[flight.command.name]++
		h.injected.Reached[flight.command.name+"/"+result.Outcome]++
		if operation.subjectKey == "" && id != nil {
			operation.subjectKey = exploreKey(id)
		}
		return nil, "", nil
	}
	if operation.retryOf != 0 {
		h.injected.Reached[flight.command.name+"/"+result.Outcome]++
	}
	if result.Consistency != "" {
		h.tokens[flight.client] = result.Consistency
	}
	operation.returned = true
	operation.returnedAt = h.clock
	operation.outcome = result.Outcome
	if operation.outcome == "" {
		operation.outcome = exploreUndeclared
	}
	if id == nil {
		return nil, "", nil
	}
	if operation.subjectKey == "" {
		operation.subjectKey = exploreKey(id)
	}
	return id, entity, nil
}

func exploreUUID(n uint64) string {
	return fmt.Sprintf("00000000-0000-4000-8000-%012x", n)
}

// exploreQuote is a JSON string as `ess` writes one: no HTML escaping.
func exploreQuote(text string) string {
	var out strings.Builder
	encoder := json.NewEncoder(&out)
	encoder.SetEscapeHTML(false)
	_ = encoder.Encode(text)
	return strings.TrimSuffix(out.String(), "\n")
}

// exploreHistoryBytes is the history in the one spelling `ess` reads and writes: compact, keys in
// declaration order, an absent `returned_at` and `outcome` for a call that never answered.
func exploreHistoryBytes(digest string, seed, clients int, operations []exploreOperation) []byte {
	written := []string{}
	kept := []exploreOperation{}
	// position is where each written operation stands among the written ones, from 1, for a retry
	// naming it.
	position := map[int]int{}
	// named is every subject a written operation names.
	named := map[string]bool{}
	for index, operation := range operations {
		if !operation.dropped {
			position[index] = len(kept) + 1
			kept = append(kept, operation)
			if operation.subjectKey != "" {
				named[operation.subjectKey] = true
			}
		}
	}
	for index, operation := range kept {
		members := [][2]string{
			{"operation_id", exploreQuote(exploreUUID(uint64(index) + 1))},
			{"client", strconv.Itoa(operation.client)},
			{"command", exploreQuote(operation.command)},
			{"subject_key", exploreQuote(operation.subjectKey)},
			{"invoked_at", strconv.Itoa(operation.invokedAt)},
		}
		if operation.returned {
			members = append(members,
				[2]string{"returned_at", strconv.Itoa(operation.returnedAt)},
				[2]string{"completion", exploreQuote("Returned")},
				[2]string{"outcome", exploreQuote(operation.outcome)})
			if operation.rows != nil {
				rows := exploreWrittenRows(operation, named, kept)
				quoted := make([]string, 0, len(rows))
				for _, row := range rows {
					quoted = append(quoted, exploreQuote(row))
				}
				members = append(members, [2]string{"rows", "[" + strings.Join(quoted, ",") + "]"})
			}
		} else {
			members = append(members, [2]string{"completion", exploreQuote("Indeterminate")})
		}
		if original := position[operation.retryOf-1]; operation.retryOf != 0 && original != 0 {
			members = append(members, [2]string{"retry_of", exploreQuote(exploreUUID(uint64(original)))})
		}
		written = append(written, exploreJSONObject(members))
	}
	return []byte(exploreJSONObject([][2]string{
		{"format", exploreQuote("ess-history/1")},
		{"history_id", exploreQuote(exploreUUID(uint64(seed) & 0xffffffffffff))},
		{"spec_digest", exploreQuote(digest)},
		{"seed", strconv.Itoa(seed)},
		{"clients", strconv.Itoa(clients)},
		{"operations", "[" + strings.Join(written, ",") + "]"},
	}))
}

// exploreJSONObject is a JSON object of members, in the order given, each value already written.
func exploreJSONObject(members [][2]string) string {
	parts := make([]string, 0, len(members))
	for _, member := range members {
		parts = append(parts, exploreQuote(member[0])+":"+member[1])
	}
	return "{" + strings.Join(parts, ",") + "}"
}

// exploreRecordHistory records the history seed names against a fresh target.
func exploreRecordHistory(p *explorePlan, newTarget func() Target, digest string, seed int, options ConcurrentOptions) ([]byte, *exploreRecording, error) {
	r := NewMulberry32(uint32(seed))
	clients := options.Clients
	if clients == 0 {
		clients = r.Int(2, 4)
	}
	calls := options.Calls
	if calls == 0 {
		calls = exploreConcurrentCalls
	}
	target := newTarget()
	scenario := ScenarioContext{Scenario: fmt.Sprintf("explore/concurrent/seed-%d", seed), Correlation: NewHarness(p.system).Correlation()}
	if err := target.BeginScenario(scenario); err != nil {
		return nil, nil, err
	}
	defer func() { _ = target.EndScenario(scenario) }()
	h := &exploreRecording{target: target, correlation: scenario.Correlation, ir: p.ir, arranging: true, retries: make([]*exploreRetry, clients), injected: newConcurrentInjected(), tokens: make([]string, clients)}
	if options.Inject {
		h.injection = NewSplitMix64(uint64(seed) ^ exploreInjectionStream)
	}
	model := &exploreModel{records: map[string][]*exploreRecord{}}

	// The prefix: creations on client 0, one at a time, so the clients have subjects to share.
	creating := []*exploreCommand{}
	for _, command := range p.commands {
		for _, node := range exploreList(command.node["outcomes"]) {
			if exploreObject(exploreObject(node)["subject"])["effect"] == "creates" {
				creating = append(creating, command)
				break
			}
		}
	}
	for index := 0; index < exploreConcurrentPrefix && len(creating) > 0; index++ {
		command := explorePick(r, creating)
		step := exploreDrawStep(command, r, model)
		if step == nil {
			continue
		}
		id, entity, err := h.complete(h.invoke(0, command, step))
		if err != nil {
			return nil, nil, err
		}
		if id != nil {
			model.records[entity] = append(model.records[entity], &exploreRecord{id: id, fields: Row{}})
		}
	}

	// The workload: each client's calls, drawn against the subjects the prefix created. A call is
	// one of the commands or a read of one of the views, each as likely as another.
	workload := make([][]exploreCall, clients)
	for client := range workload {
		for call := 0; call < calls; call++ {
			for attempt := 0; attempt < exploreAttempts; attempt++ {
				choice := r.Int(0, len(p.commands)+len(p.views)-1)
				if choice >= len(p.commands) {
					workload[client] = append(workload[client], exploreCall{view: p.views[choice-len(p.commands)]})
					break
				}
				command := p.commands[choice]
				if step := exploreDrawStep(command, r, model); step != nil {
					workload[client] = append(workload[client], exploreCall{command: command, step: step})
					break
				}
			}
		}
	}

	// The interleaving: the clients' moves first, in client order, then each client's retry, then
	// each queued second delivery. Without Inject only the first kind exists.
	h.arranging = false
	draw := NewSplitMix64(uint64(seed))
	next := make([]int, clients)
	flying := make([]*exploreFlight, clients)
	for {
		enabled := [][2]int{}
		for client := range workload {
			if flying[client] != nil || (h.retries[client] == nil && next[client] < len(workload[client])) {
				enabled = append(enabled, [2]int{0, client})
			}
		}
		for client := range workload {
			if h.retries[client] != nil {
				enabled = append(enabled, [2]int{1, client})
			}
		}
		for slot := range h.redeliveries {
			enabled = append(enabled, [2]int{2, slot})
		}
		if len(enabled) == 0 {
			break
		}
		move := enabled[draw.below(len(enabled))]
		client := move[1]
		if move[0] == 1 {
			retry := h.retries[client]
			if retry.flight == nil {
				retry.flight = h.invokeRetry(client, retry)
			} else {
				h.retries[client] = nil
				if _, _, err := h.complete(retry.flight); err != nil {
					return nil, nil, err
				}
			}
		} else if move[0] == 2 {
			h.redeliver(move[1])
		} else if flying[client] != nil {
			if _, _, err := h.complete(flying[client]); err != nil {
				return nil, nil, err
			}
			flying[client] = nil
		} else {
			call := workload[client][next[client]]
			next[client]++
			if call.view != nil {
				flying[client] = h.invokeRead(client, call.view)
			} else {
				flying[client] = h.invoke(client, call.command, call.step)
			}
		}
	}
	return exploreHistoryBytes(digest, seed, clients, h.operations), h, nil
}

// ExploreConcurrent records one concurrent history per seed against a fresh target, writes each
// into Out, and runs `ess verify conform check-history --path Path` on it.
//
// It returns an error when `ess` is not on PATH (ErrNoEss, before any target is made), when the
// model cannot be used, when a history cannot be written, and when `ess` refuses one: a history
// nobody could check is not a verdict. A violation or an unknown verdict is in the result.
func ExploreConcurrent(newTarget func() Target, options ConcurrentOptions) (ConcurrentResult, error) {
	if options.Clients != 0 && (options.Clients < 2 || options.Clients > 4) {
		return ConcurrentResult{}, fmt.Errorf("explore: `Clients` is %d; concurrent exploration runs 2 to 4 clients, or draws how many from each seed when it is 0", options.Clients)
	}
	if options.Seeds < 0 {
		return ConcurrentResult{}, fmt.Errorf("explore: `Seeds` is %d; concurrent exploration records at least one history, or 200 when it is 0", options.Seeds)
	}
	if options.Seed < 0 {
		return ConcurrentResult{}, fmt.Errorf("explore: `Seed` is %d; a replayed seed is at least 1, or none when it is 0", options.Seed)
	}
	if options.Calls < 0 {
		return ConcurrentResult{}, fmt.Errorf("explore: `Calls` is %d; each client makes at least one call, or 3 when it is 0", options.Calls)
	}
	ess, err := exec.LookPath("ess")
	if err != nil {
		return ConcurrentResult{}, ErrNoEss
	}
	if options.Path == "" {
		return ConcurrentResult{}, errors.New("explore: concurrent exploration needs `Path`, the specification `ess` checks each history against")
	}
	if options.Out == "" {
		return ConcurrentResult{}, errors.New("explore: concurrent exploration needs `Out`, the directory each history is written into")
	}
	ir, err := exploreLoad(exploreIR, exploreSuite)
	if err != nil {
		return ConcurrentResult{}, err
	}
	if exploreNonEmpty(ir["preconditions"]) {
		return ConcurrentResult{}, errors.New("explore: concurrent exploration does not run the specification's preconditions, so it does not record against one that declares them")
	}
	suite, _ := strictJSON(exploreSuite)
	digest := exploreString(exploreObject(exploreObject(suite)["provenance"])["spec_digest"])
	p := explorePlanAs(ir, true)
	if len(p.commands) == 0 {
		return ConcurrentResult{}, errors.New("explore: the specification declares no command concurrent exploration can call")
	}
	if err := os.MkdirAll(options.Out, 0o755); err != nil {
		return ConcurrentResult{}, fmt.Errorf("explore: cannot create %s: %w", options.Out, err)
	}
	seeds := []int{}
	if options.Seed != 0 {
		seeds = append(seeds, options.Seed)
	} else {
		count := options.Seeds
		if count == 0 {
			count = exploreConcurrentSeeds
		}
		for seed := 1; seed <= count; seed++ {
			seeds = append(seeds, seed)
		}
	}
	result := ConcurrentResult{Verdicts: []string{}, Excluded: []Exclusion{}, AllowExcluded: options.AllowExcluded, Injected: newConcurrentInjected()}
	for _, seed := range seeds {
		if len(p.commands) == 0 {
			break
		}
		bytes, recording, err := exploreRecordHistory(p, newTarget, digest, seed, options)
		if err != nil {
			return ConcurrentResult{}, fmt.Errorf("explore: seed %d: %w", seed, err)
		}
		result.Indeterminate += recording.indeterminate
		result.Injected.add(recording.injected)
		for _, exclusion := range recording.unsupported {
			known := false
			for _, earlier := range result.Excluded {
				known = known || earlier.Subject == exclusion.Subject
			}
			if !known {
				result.Excluded = append(result.Excluded, exclusion)
			}
		}
		name := fmt.Sprintf("history-%d.json", seed)
		file := filepath.Join(options.Out, name)
		if err := os.WriteFile(file, bytes, 0o644); err != nil {
			return ConcurrentResult{}, fmt.Errorf("explore: cannot write %s: %w", file, err)
		}
		var stdout, stderr strings.Builder
		check := exec.Command(ess, "verify", "conform", "check-history", "--path", options.Path, "--history", file)
		check.Stdout = &stdout
		check.Stderr = &stderr
		code := 0
		if err := check.Run(); err != nil {
			var exit *exec.ExitError
			if !errors.As(err, &exit) {
				return ConcurrentResult{}, fmt.Errorf("explore: cannot run `ess`: %w", err)
			}
			code = exit.ExitCode()
		}
		verdict := ""
		switch code {
		case 0:
			verdict = "Linearizable"
			result.Linearizable++
		case 1:
			verdict = "Violation"
			result.Violations++
		case 3:
			verdict = "Unknown"
			result.Unknown++
		default:
			return ConcurrentResult{}, fmt.Errorf("explore: `ess verify conform check-history` refused %s (exit %d): %s", name, code, strings.TrimSpace(stderr.String()))
		}
		result.Histories++
		result.Verdicts = append(result.Verdicts, verdict)
		if verdict != "Linearizable" && result.Failure == nil {
			result.Failure = &ConcurrentFailure{Seed: seed, Verdict: verdict, History: name, Report: stdout.String()}
		}
	}
	return result, nil
}

// CheckConcurrent is what AssertConcurrent would fail with, or nil when every history was
// linearizable. `Unknown` is never a pass.
func CheckConcurrent(result ConcurrentResult) error {
	problems := []string{}
	if result.Violations != 0 || result.Unknown != 0 {
		message := fmt.Sprintf("explore: %d of %d concurrent histories were violations and %d unknown", result.Violations, result.Histories, result.Unknown)
		if failure := result.Failure; failure != nil {
			message += fmt.Sprintf("\nseed %d (%s): %s\n%s", failure.Seed, failure.History, failure.Verdict, strings.TrimRight(failure.Report, "\n"))
		}
		problems = append(problems, message)
	}
	if len(result.Excluded) > 0 && !result.AllowExcluded {
		lines := []string{}
		for _, exclusion := range result.Excluded {
			lines = append(lines, fmt.Sprintf("  %s: %s", exclusion.Subject, exclusion.Reason))
		}
		problems = append(problems, fmt.Sprintf("explore: %d command(s) the target does not expose were left out of concurrent exploration:\n%s\naccept them explicitly with ConcurrentOptions{AllowExcluded: true}", len(result.Excluded), strings.Join(lines, "\n")))
	}
	if len(problems) == 0 {
		return nil
	}
	return errors.New(strings.Join(problems, "\n"))
}

// AssertConcurrent fails t unless every concurrent history was linearizable.
func AssertConcurrent(t testing.TB, result ConcurrentResult) {
	t.Helper()
	if err := CheckConcurrent(result); err != nil {
		t.Fatal(err)
	}
}
